            .onboardingPrimaryLanguageTitle: "Основной язык",
            .onboardingPrimaryLanguageHint: "Язык, на котором вы обычно диктуете.",
            .onboardingPrimaryLanguageBody: "Основной язык: %@",
            .onboardingAdditionalLanguageTitle: "Дополнительный язык",
            .onboardingAdditionalLanguageHint: "Второй язык, которым вы часто пользуетесь.",
            .onboardingAdditionalLanguageBody: "Дополнительный язык: %@",
            .onboardingAdditionalSameAsPrimary: "Как основной",
            .languagePairSectionTitle: "Ваши языки",
            .primaryLanguage: "Основной язык",
            .primaryLanguageHint: "Язык, на котором вы обычно диктуете.",
            .additionalLanguage: "Дополнительный язык",
            .additionalLanguageHint: "Второй язык, которым вы часто пользуетесь.",
            .additionalSameAsPrimary: "Как основной",
            .languagePairEngineNote: "Parakeet и Whisper по умолчанию по-прежнему автоматически определяют вашу речь. Ваши два языка — это языки по умолчанию, которые используются при переключении языков на HUD.",
            .helpBilingualTitle: "Ваши языки",
            .helpBilingualIntro: "Bolabol работает с двумя языками: основным (тем, на котором вы обычно диктуете) и дополнительным (вторым языком, которым вы часто пользуетесь). Это не модель «всегда выводить в целевой язык» — дополнительный язык это просто ваш второй язык для быстрого переключения.",
            .helpBilingualPrimary: "Основной язык — это ваш обычный язык диктовки. Распознавание речи и вывод Raw по умолчанию используют этот язык. HUD показывает A (автоопределение), когда вы говорите на основном языке.",
            .helpBilingualAdditional: "Дополнительный язык — это второй язык, которым вы часто пользуетесь. На HUD нажмите левую кнопку, чтобы переключиться с A на букву, обозначающую этот язык (E, S, R, F, C, G, …), и принудительно выводить текст на нём. Нажмите ещё раз, чтобы вернуться к A.",
            .helpBilingualNotAlwaysOutput: "Важно: дополнительный язык — это не настройка «всегда выводить в целевой язык». Вы можете диктовать на любом языке; буква на HUD просто позволяет быстро выбрать язык вывода для этой сессии. Вывод Raw по-прежнему соответствует тому, что вы реально сказали, если вы не задали целевой язык принудительно.",
            .helpBilingualWhere: "Задайте оба языка в онбординге или измените их в любое время: Настройки → Горячая клавиша → Ваши языки. Эта пара также определяет выбор букв на HUD.",
            .helpBilingualOnboarding: "Онбординг запрашивает ваш основной и дополнительный языки (план §6.1). Если вы его пропустили, значения по умолчанию берутся из системной локали.",
            .helpBilingualSettingsPath: "Настройки → Горячая клавиша → Ваши языки.",
            .helpBilingualCanary: "Canary работает только как распознавание речи. Исходный язык нужно явно выбрать в Настройках; режима автоопределения и перевода речи у него нет.",
            .helpBilingualHUD: "Canary работает только как транскрипция. Управление языком на HUD не превращает его в движок перевода речи.",
            .helpBilingualAutoEngines: "Parakeet и Whisper могут использовать автоопределение. Canary требует явно заданного исходного языка и выдаёт только транскрипцию.",
            .helpBilingualPolishNote: "Полировка (MLX или облако) выполняется после распознавания, но не на Canary. Она улучшает текст на том языке, на котором сделана расшифровка, — она не меняет язык.",

