            .languagePairEngineNote: "Parakeet y Whisper siguen detectando tu habla automáticamente de forma predeterminada. Tus dos idiomas son tus opciones predeterminadas y se usan al cambiar de idioma en el HUD.",
            .helpBilingualTitle: "Tus idiomas",
            .helpBilingualIntro: "Bolabol funciona con dos idiomas: un idioma principal (aquel en el que dictas normalmente) y un idioma adicional (un segundo idioma que usas con frecuencia). No es un modelo de «salida obligada a un idioma fijo»: el idioma adicional es simplemente tu segundo idioma para cambiar con rapidez.",
            .helpBilingualPrimary: "Idioma principal = tu idioma habitual de dictado. El reconocimiento de voz y la salida Raw usan este idioma por defecto. El HUD muestra A (detección automática) cuando hablas en tu idioma principal.",
            .helpBilingualAdditional: "Idioma adicional = un segundo idioma que usas con frecuencia. En el HUD, toca el botón izquierdo para pasar de A a la letra que representa este idioma (E, S, R, F, C, G, …) y forzar esa salida. Vuelve a tocar para regresar a A.",
            .helpBilingualNotAlwaysOutput: "Importante: el idioma adicional no es un ajuste de salida siempre hacia un idioma fijo. Puedes dictar en cualquier idioma; la letra del HUD solo te permite elegir rápidamente el idioma de salida para esta sesión. La salida Raw sigue el idioma que realmente hablaste, salvo que fuerces un destino.",
            .helpBilingualWhere: "Configura tus dos idiomas en la configuración inicial o cámbialos en cualquier momento en Ajustes → Atajo → Tus idiomas. Este par también define las opciones de letra del HUD.",
