            .additionalSameAsPrimary: "Wie die Primärsprache",
            .languagePairEngineNote: "Parakeet und Whisper erkennen Ihre Sprache standardmäßig weiterhin automatisch. Ihre beiden Sprachen sind die Standardsprachen und werden beim Sprachwechsel auf dem HUD verwendet.",
            .helpBilingualTitle: "Ihre Sprachen",
            .helpBilingualIntro: "Bolabol arbeitet mit zwei Sprachen: einer Primärsprache (der Sprache, in der Sie normalerweise diktieren) und einer Zusatzsprache (einer zweiten Sprache, die Sie häufig verwenden). Die Zusatzsprache erzwingt dabei keine dauerhaft festgelegte Ausgabe — sie ist schlicht Ihre zweite Sprache für den schnellen Wechsel.",
            .helpBilingualPrimary: "Primärsprache = Ihre übliche Diktiersprache. Spracherkennung und Raw-Ausgabe verwenden standardmäßig diese Sprache. Das HUD zeigt A (automatische Erkennung), wenn Sie in Ihrer Primärsprache sprechen.",
            .helpBilingualAdditional: "Zusatzsprache = eine zweite Sprache, die Sie häufig verwenden. Tippen Sie auf dem HUD auf die linke Taste, um von A auf den Buchstaben dieser Sprache (E, S, R, F, C, G, …) zu wechseln und diese Ausgabe zu erzwingen. Tippen Sie erneut, um zu A zurückzukehren.",
            .helpBilingualNotAlwaysOutput: "Wichtig: Die Zusatzsprache ist keine Einstellung, die die Ausgabe immer in eine bestimmte Sprache zwingt. Sie können in jeder Sprache diktieren; der HUD-Buchstabe erlaubt Ihnen lediglich, die Ausgabesprache für diese Sitzung schnell zu wählen. Die Raw-Ausgabe folgt weiterhin dem, was Sie tatsächlich gesprochen haben — es sei denn, Sie erzwingen eine Zielsprache.",
            .helpBilingualWhere: "Legen Sie Ihre beiden Sprachen im Onboarding fest oder ändern Sie sie jederzeit unter Einstellungen → Kurzbefehl → Ihre Sprachen. Dieses Sprachpaar steuert auch die Buchstabenwahl auf dem HUD.",
            .helpBilingualOnboarding: "Das Onboarding fragt nach Ihrer Primär- und Zusatzsprache (Plan §6.1). Wenn Sie es übersprungen haben, werden die Standardwerte aus Ihrer Systemsprache abgeleitet.",
            .helpBilingualSettingsPath: "Einstellungen → Kurzbefehl → Ihre Sprachen.",
            .helpBilingualCanary: "Canary dient nur der Spracherkennung. Wählen Sie in den Einstellungen eine Quellsprache; automatische Erkennung und Sprachübersetzung werden nicht unterstützt.",
            .helpBilingualHUD: "Canary erstellt nur Transkripte. Die Sprachsteuerung im HUD macht daraus keine Sprachübersetzungs-Engine.",
            .helpBilingualAutoEngines: "Parakeet und Whisper können die automatische Erkennung verwenden. Canary benötigt eine explizite Quellsprache und erstellt nur ein Transkript.",
            .helpBilingualPolishNote: "Polishing (MLX oder Cloud) läuft nach der Transkription, nicht bei Canary. Es verbessert den Text in der Sprache, in der das Transkript vorliegt — es ändert die Sprache nicht.",

