            .onboardingGlossaryExplanation: "Un glossaire aide Bolabol à écrire les noms, termes spécialisés, abréviations et mots souvent mal reconnus exactement comme vous le souhaitez. Ajoutez l’orthographe correcte et les variantes courantes ; après la transcription ou la traduction, Bolabol remplace automatiquement ces variantes par votre forme préférée. Le glossaire reste sur ce Mac et peut être modifié à tout moment dans Réglages.",
