            .languagePairEngineNote: "Par défaut, Parakeet et Whisper détectent toujours automatiquement la langue que vous parlez. Vos deux langues sont vos valeurs par défaut et servent lors des changements de langue sur le HUD.",
            .helpBilingualTitle: "Vos langues",
            .helpBilingualIntro: "Bolabol fonctionne avec deux langues : une langue principale (celle dans laquelle vous dictez habituellement) et une langue supplémentaire (une deuxième langue que vous utilisez souvent). Ce n'est pas un modèle de «langue de sortie imposée» — la langue supplémentaire est simplement votre deuxième langue, pour un basculement rapide.",
            .helpBilingualPrimary: "Langue principale = votre langue de dictée habituelle. La reconnaissance vocale et la sortie Raw utilisent cette langue par défaut. Le HUD affiche A (détection automatique) lorsque vous parlez dans votre langue principale.",
            .helpBilingualAdditional: "Langue supplémentaire = une deuxième langue que vous utilisez souvent. Sur le HUD, touchez le bouton gauche pour passer de A à la lettre représentant cette langue (E, S, R, F, C, G, …) et forcer cette sortie. Touchez à nouveau pour revenir à A.",
            .helpBilingualNotAlwaysOutput: "Important : la langue supplémentaire n'est pas un paramètre qui impose une langue de sortie. Vous pouvez dicter dans n'importe quelle langue ; la lettre du HUD vous permet simplement de choisir rapidement la langue de sortie de la session. La sortie Raw suit ce que vous avez réellement dit, sauf si vous forcez une langue cible.",
            .helpBilingualWhere: "Définissez vos deux langues lors de l'installation initiale, ou modifiez-les à tout moment dans Réglages → Raccourci → Vos langues. Cette paire détermine aussi les choix de lettre du HUD.",
            .helpBilingualOnboarding: "L'installation initiale vous demande vos langues principale et supplémentaire (plan §6.1). Si vous l'avez ignorée, les valeurs par défaut sont dérivées de la langue de votre système.",
            .helpBilingualSettingsPath: "Réglages → Raccourci → Vos langues.",
            .helpBilingualCanary: "Canary sert uniquement à la reconnaissance vocale. Choisissez une langue source explicite dans Réglages ; la détection automatique et la traduction vocale ne sont pas prises en charge.",
            .helpBilingualHUD: "Canary produit uniquement des transcriptions. Le contrôle de langue du HUD n'en fait pas un moteur de traduction vocale.",
            .helpBilingualAutoEngines: "Parakeet et Whisper peuvent utiliser la détection automatique. Canary exige une langue source explicite et produit uniquement une transcription.",
            .helpBilingualPolishNote: "La révision (MLX ou cloud) s'exécute après la transcription, pas sur Canary. Elle améliore le texte dans la langue de la transcription — elle n'en change pas la langue.",

