            .helpBilingualTitle: "Le tue lingue",
            .helpBilingualIntro: "Bolabol funziona con due lingue: una lingua principale (quella in cui detti di solito) e una lingua aggiuntiva (una seconda lingua che usi spesso). Non è un modello che forza sempre l'output verso una lingua: la lingua aggiuntiva è semplicemente la tua seconda lingua per cambiare rapidamente.",
            .helpBilingualPrimary: "Lingua principale = la tua lingua di dettatura abituale. Il riconoscimento vocale e l'output Raw usano questa lingua per impostazione predefinita. L'HUD mostra A (auto-detect) quando parli nella tua lingua principale.",
            .helpBilingualAdditional: "Lingua aggiuntiva = una seconda lingua che usi spesso. Sull'HUD, tocca il pulsante di sinistra per passare da A alla lettera che rappresenta questa lingua (E, S, R, F, C, G, …) e forzarne l'output. Tocca di nuovo per tornare ad A.",
            .helpBilingualNotAlwaysOutput: "Importante: la lingua aggiuntiva non è un'impostazione che forza sempre l'output verso una lingua. Puoi dettare in qualsiasi lingua; la lettera sull'HUD ti permette semplicemente di scegliere rapidamente la lingua di output per questa sessione. L'output Raw segue comunque ciò che hai effettivamente detto, a meno che tu non forzi una destinazione.",
            .helpBilingualWhere: "Imposta le tue due lingue nella configurazione iniziale, oppure modificale in qualsiasi momento in Impostazioni → Scorciatoia → Le tue lingue. Questa coppia determina anche le scelte delle lettere sull'HUD.",
            .helpBilingualOnboarding: "La configurazione iniziale richiede la tua lingua principale e aggiuntiva (piano §6.1). Se la salti, i valori predefiniti derivano dalle impostazioni internazionali del sistema.",
