            .helpBilingualIntro: "O Bolabol funciona com dois idiomas: um idioma principal (aquele em que você costuma ditar) e um idioma adicional (um segundo idioma que você usa com frequência). Este não é um modelo de \"saída sempre no idioma alvo\" — o idioma adicional é simplesmente o seu segundo idioma para alternância rápida.",
            .helpBilingualPrimary: "Idioma principal = seu idioma habitual de ditado. O reconhecimento de fala e a saída Raw usam esse idioma por padrão. O HUD mostra A (detecção automática) quando você está falando no seu idioma principal.",
            .helpBilingualAdditional: "Idioma adicional = um segundo idioma que você usa com frequência. No HUD, toque no botão esquerdo para alternar de A para a letra que representa esse idioma (E, S, R, F, C, G, …) e forçar essa saída. Toque novamente para voltar a A.",
            .helpBilingualNotAlwaysOutput: "Importante: o idioma adicional não é uma configuração de \"saída sempre no idioma alvo\". Você pode ditar em qualquer idioma; a letra do HUD apenas permite escolher rapidamente o idioma de saída desta sessão. A saída Raw continua seguindo o que você realmente falou, a menos que force um idioma alvo.",
