            .helpHeroSubtitle: "Mac のどこからでも音声入力。音声は Whisper でデバイス上で文字起こしされ、テキストは Raw のまま、クリーンアップ、または書き直しができ、その後コピーまたは使用中の App に入力できます。",
            .helpStartTitle: "ここから始めましょう（最初の 5 分）",
            .helpStart1: "macOS が尋ねたらマイクを許可してください。許可しないと録音を開始できません。",
            .helpStart2: "「設定 → ローカルモデル」を開き、Whisper モデルをダウンロード（Large v3 Full が最もバランスの良い選択）して「使用」を押します。",
            .helpStart3: "「設定 → ホットキー」を開き、ホットキーをオンにします。プライマリ（デフォルト Option+S）は音声入力です。翻訳ウィンドウのホットキー（デフォルト Option+1）は完全なフローティング翻訳パネルを開き、クイック翻訳（デフォルト Option+2）は結果のみを表示、設定を開く（デフォルト Option+~）は環境設定を開きます。音声入力ではターゲット（Raw / バリアント 1 / バリアント 2）とモード（クリップボードまたはアクティブな App に入力）を選びます。",
            .helpStart4: "任意：API プロバイダでクラウドキーを追加（プロバイダごとに複数保存可）し、モデルを選び、お気に入りに星を付け、「使用」で推敲 — またはローカル MLX モデルをインストール。推敲/翻訳エンジンがないと、バリアント 1/2 と英語以外の強制言語はテキストを改善しません。",
            .helpStart5: "音声入力：任意の App にフォーカス → Option+S → 話す → もう一度 Option+S（赤 HUD = 録音中、緑 = 処理中）。即時翻訳：他でテキストを選択 → Option+1 → フローティングパネルが選択/クリップボードを取得して翻訳（Option+2 は結果のみ表示）。",
            .helpModesTitle: "4 つの作業方法",
            .helpModeWindowTitle: "メインウィンドウ",
            .helpModeWindowBody: "メモのためのノート：音声を録音または読み込み、Raw / バリアント 1 / バリアント 2 を確認、推敲、翻訳、コピー。編集して履歴を残したい場合に最適。",
            .helpModeHotkeyTitle: "ホットキー + オーバーレイ HUD",
            .helpModeHotkeyBody: "他の App の中に留まります。プライマリホットキー（Option+S）はフローティング HUD で録音：言語モード（A / 文字）と出力ターゲット（R / 1 / 2）。HUD表示中にスクロールするとポリッシングプロバイダーを切り替えられ、プロバイダーを右クリックすると特定のモデルを選べます。音声入力中にキーボードフォーカスを奪いません。",
            .helpModeFloatTitle: "フローティング翻訳ウィンドウ",
            .helpModeFloatBody: "翻訳ウィンドウのホットキー（デフォルト Option+1）は常に最前面の翻訳パネルを開きます。アクティブな App から選択テキストを取得し（素早い Command-C で）、原文を入力して即座に翻訳できます。完全な音声入力なしの言語切替に便利。",
            .helpWindowTitle: "メインウィンドウ",
            .helpWindowBody: "左：メモ一覧。右：選択中のメモ — 音声情報、推敲プロバイダ/モデルメニュー、テキストタブ、アクションバー。",
            .helpWindowNotes: "サイドバー：メモを選択、すべてコピー、またはすべてクリア（永久：すべてのメモとディスク上の残存録音ファイルを削除）。",
            .helpWindowTabs: "タブ：Raw = 純粋な文字起こし。バリアント 1 = 軽いクリーンアップ（フィラー、繰り返し）。バリアント 2 = 明瞭さのためのより強い書き直し。推敲済みタブで Markdown アクションを使いテキストを構造化。プロンプトスロット D/1/2/3/4 でそのバリアントに有効なカスタムプロンプトを切り替え。",
            .helpWindowActions: "下部バー：録音 / 停止、空のメモ、音声を読み込む（またはファイルをウィンドウにドラッグ）、翻訳、推敲、コピー。設定で環境設定を開く。",
            .helpWindowPolishingMenus: "エディタの上で推敲プロバイダ（無効 / クイッククリーンアップ / ローカル MLX / クラウド）と推敲モデル（選択中のクラウドプロバイダのモデル、またはローカル MLX カード）を切り替えられます。これはメモを離れずに「設定 → API プロバイダ / 推敲」と一致します。",
            .helpHUDTitle: "オーバーレイ HUD（フローティングカプセル）",
            .helpHUDIntro: "グローバルホットキーを押すと、すべての App の上に小さなフローティングカプセルが表示されます。通常のウィンドウではなく、常に最前面に留まり、キーボードフォーカスを奪わず、状態のみを表示します — 完全な文字起こしではありません。",
            .helpHUDAnatomy: "レイアウト 左 → 右：(1) 言語ボタン · (2) 中央のライブ波形 · (3) 出力ターゲットボタン。画面上では多くの場合 [ A ] ≈≈≈ [ R ] のように見えます。",
            .helpHUDColorRed: "マイク録音中に中央の波形が赤くなります。赤いうちに話してください。",
            .helpHUDColorGreen: "停止後（もう一度ホットキー）、波形が緑になります：Bolabol が文字起こし、必要に応じて推敲し、テキストを渡しています。HUD が消えるまで待ってください。",
            .helpHUDLeftTitle: "左ボタン — 言語モード（A ↔ 文字）",
            .helpHUDLeftA: "A ＝ Auto。Bolabol は話した言語を自動検出します。文字起こしはその言語のままになります（デフォルトでは主要言語）。強制変換は行われません。話した言語のまま Raw 出力したい場合に使用します。",
            .helpHUDLeftLetter: "A の代わりに文字が表示されている場合は「出力言語の強制」を意味します。文字はその言語の英語名の頭文字です。E ＝ English、S ＝ Spanish、R ＝ Russian、F ＝ French、C ＝ Chinese、G ＝ German…という具合です。文字はデフォルトで、設定 → ホットキー → あなたの言語で設定した追加言語になります。ホットキー → 文字起こし言語が特定の言語に設定されている場合は、その言語が文字になります。",
            .helpHUDLeftTap: "左ボタンを1回タップすると A → 文字（追加言語への強制出力）に切り替わり、もう一度タップすると文字 → A（自動検出）に戻ります。選択した内容は次回のセッションまで記憶されます。",
            .helpHUDRightTitle: "右ボタン — 出力ターゲット（R → 1 → 2）",
            .helpHUDRightR: "R = Raw。バリアント 1 / バリアント 2 の推敲なしで plain な文字起こしを渡します。最速パス；左ボタンが E のときは Whisper の英語翻訳を使用可能。",
            .helpHUDRightCycle: "1 = バリアント 1（軽いクリーンアップ）。2 = バリアント 2（より強い書き直し）。これらは有効な推敲エンジン（クラウドまたはローカル MLX）が必要。1 または 2 を選ぶと、無効だった推敲が再度オンになります。",
            .helpHUDRightTap: "右ボタンをタップで R → 1 → 2 → R を循環。選択は今後の音声入力向けにホットキー設定の新しいデフォルトターゲットになります。",
            .helpHUDControlLanguage: "左：A ＝ 自動検出（文字起こしは話した言語）。文字（E、S、R…）＝ その言語への強制出力（デフォルト ＝ 追加言語）。タップで A ↔ 文字を切り替えます。",
            .helpHUDControlTarget: "右：R = Raw 文字起こし、1 = バリアント 1、2 = バリアント 2。タップで R → 1 → 2 → R を循環。",
            .helpHUDDrag: "ドラッグ：カプセルの任意の場所（ボタンだけでなく）をクリックして保持し、任意のディスプレイの任意の場所に移動。隅の近く、Dock の上、または入力する App の隣に — 好きな場所に置いてください。",
            .helpHUDSize: "サイズと透明度：設定 → 一般 → オーバーレイ HUD。サイズスライダはカプセル全体（および表示されるスペクトルバーの数）を拡大縮小。透明度はガラス背景を薄め、デスクトップの内容を多かれ少なかれ透かします。",
            .helpHUDSound: "サウンド：同じ一般 → オーバーレイ HUD セクション。「開始/終了時にサウンドを再生」を切替、音量を設定し、「HUD サウンドをテスト」で録音なしにプレビュー。録音開始時と処理終了時にキューが再生されます。",
            .helpHUDSettingsPath: "HUD の外観はすべて設定 → 一般 → オーバーレイ HUD の下（サイズ、透明度、サウンド、音量）。位置はドラッグ後に自動保存されます。",
            .helpHUDPosition: "HUD をドラッグすると、Bolabol はその場所を記憶し、次回そこで開きます。",
            .helpHUDDuration: "話せる長さに短い人為的制限はありません。波形が赤いうちは話し続けてください；完了したらもう一度ホットキーを押します。",
            .helpLangTitle: "言語モードの詳細",
            .helpLangIntro: "言語の制御は、HUD の左ボタン（A ↔ 文字）と、設定 → ホットキー → あなたの言語（主要 ＋ 追加）で行います。HUD の文字はデフォルトで追加言語になり、両者が連携して動作します。",
            .helpLangAuto: "A（Auto）：文字起こしは話した言語のままになります（デフォルトでは主要言語）。出力を強制せず、普段の言語でメモを取るのに最適です。",
            .helpLangForced: "文字（変換先を指定）：音声認識の後、Bolabol は文字起こしを追加言語（または選択した別の言語）で出力できます。どの言語で話しても、HUD の左ボタンをタップして A から文字（E、S、R、F、C、G…）に切り替えれば、その言語への出力が強制されます。設定 → ホットキー → あなたの言語で設定した追加言語が、文字のデフォルトになります。",
            .helpLangEnglishNote: "英語への強制変換 ＋ 多言語 Whisper：Raw は Whisper 内蔵の英語翻訳をデバイス上で使用します（高速）。品質を重視するなら Large v3 Full を推奨します。Turbo は軽量ですが、長い音声や複数言語が混ざった音声では信頼性が低くなります。これは HUD の文字が E（追加言語または選択した変換先）の場合に適用されます。",
            .helpLangOtherNote: "英語以外への強制出力（文字 ≠ E）には、Whisper の後に必ず LLM（クラウドまたはローカル MLX）が必要です。ポリッシングエンジンが有効でない場合、スペイン語やロシア語などへの言語変換はできません。",
            .helpLangWhere: "HUD の文字（変換先の指定）は、設定 → ホットキー → あなたの言語で設定した追加言語をデフォルトにします。ホットキーの言語が特定の言語に設定されている場合は、その言語が文字になります。ホットキーが Auto の場合、文字は用語集 → Auto Translation Language、次に英語にフォールバックします。言語ペアの変更は設定 → ホットキー → あなたの言語で行えます。",
            .helpModelsTitle: "ローカル文字起こしモデル",
            .helpModelsIntro: "「設定 → ローカルモデル」は Apple Silicon 上で音声をテキストに変換する WhisperKit Core ML モデルを管理します。これは推敲モデルとは別です。",
            .helpModelsCatalog: "英語のみ（Small/Medium .en）：英語しか話さない場合に高速。多言語 Small/Medium：より軽い多言語。Large v3 Turbo（約 1.6 GB）：高速な大型モデル。Large v3 Full（約 3 GB、最高品質）：精度と英語翻訳に推奨されるデフォルト。",
            .helpModelsRecommend: "混合言語と強制英語（HUD 文字 E）には多言語モデルを使用 — 理想的には Large v3 Full。英語のみモデルは他の言語を英語にネイティブ翻訳できません。",
            .helpModelsUse: "ダウンロード → 使用（有効は 1 つのみ）。削除はこの Mac からファイルを除去。Apple Speech フォールバックはありません — ローカル Whisper（ダウンロード済みモデル）または Cloud · Google Gemini（Google API キー必要）を選択。",
            .helpHotkeyTitle: "ホットキー設定",
            .helpHotkeyIntro: "「設定 → ホットキー」は 4 つの独立したグローバルショートカットを有効化。いずれかを発動させる前に「ホットキーを有効化」をオンにします。",
            .helpHotkeyPrimary: "プライマリ（デフォルト Option+S（⌥S））：オーバーレイ HUD への音声入力を開始/停止。1 回目で録音（赤）、2 回目で処理（緑）し Raw / バリアント 1 / バリアント 2 を渡します。",
            .helpHotkeyPushToTalk: "Push-to-Talk（任意）：「設定 → ホットキー」で Push-to-Talk モードをオンにすると、録音中にプライマリホットキーを押し続け、離すだけで自動的に文字起こしと推敲が行われます——1回タップして開始し、もう1回タップして停止する代わりに使えます。",
            .helpHotkeySecondary: "翻訳ウィンドウ（デフォルト Option+1）：完全なフローティング翻訳パネルを開きます。録音ホットキーではなく — 選択/クリップボードを取得して翻訳。リセット矢印で Option+1 を復元。",
            .helpHotkeyTertiary: "クイック翻訳（デフォルト Option+2）：翻訳結果のみの最小の読み取り専用ウィンドウを開きます。もう一度ホットキーまたは Esc で閉じます。",
            .helpHotkeySettings: "設定を開く（デフォルト Option+~）：どこからでも Bolabol 設定ウィンドウを開き、App を離れずにモデルや言語を切り替えられます。",
            .helpModeQuickTitle: "クイック翻訳ウィンドウ",
            .helpModeQuickBody: "第三ホットキー（デフォルト Option+2）は翻訳結果のみを表示する最小の常に最前面ウィンドウを開きます — ソースペインもボタンもなし。読んでから Esc で閉じます。編集や再翻訳には完全なフローティング翻訳ウィンドウを使ってください。",
            .helpFloatQuick: "2 つの翻訳ウィンドウ：フローティング翻訳ウィンドウ（Option+1）はソーステキスト、プロバイダ/モデルメニュー、コントロール付きの完全なパネル；クイック翻訳（Option+2）は結果のみを表示する最小の読み取り専用ウィンドウ。翻訳を読むだけならクイック翻訳を使ってください。",
            .helpHotkeyTarget: "音声入力ターゲット：録音後にどのテキストを渡すか — Raw、バリアント 1、またはバリアント 2。HUD の右ボタン（R / 1 / 2）と同じ選択。",
            .helpHotkeyMode: "音声入力モード：クリップボードは結果をコピーして貼り付け可能に；アクティブな App に入力は録音開始時にフォーカスされていたフィールドに挿入。",
            .helpHotkeyAccess: "アクティブな App に入力はアクセシビリティ権限が必要（同じ設定ページ）。クリップボードモードとフローティング翻訳ウィンドウはパネルへの貼り付けにアクセシビリティ不要 — ただし Command-C での他 App からのテキスト取得は App が信頼されていると最も良く動作。",
            .helpFloatTitle: "フローティング翻訳ウィンドウ",
            .helpFloatIntro: "サイズ変更可能で常に最前面のユーティリティパネル（Bolabol Translation）、メインノートとは別。ブラウザ、メール、チャットに留まりながらの素早い言語切替に最適。",
            .helpFloatHotkey: "翻訳ウィンドウのホットキーで開く（設定 → ホットキー → 翻訳ウィンドウ、デフォルト Option+1）。メインウィンドウ下部バーから「翻訳」も開けます；フローティングパネルは同じ UI を共有。",
            .helpFloatCapture: "開くと、Bolabol は最前面 App に素早く Command-C を送り選択をコピーし、Bolabol 内ならメモの選択を優先、そうでなければクリップボードテキスト。何かが取得され翻訳プロバイダが設定されていれば、翻訳が自動開始。",
            .helpFloatPanel: "パネル内：プロバイダとモデルを選択、ターゲット言語を設定、原文を編集、翻訳 / 再度翻訳を実行、または翻訳用に短いクリップを録音。パネルは他の App の上にフローティングしサイズ変更可能。",
            .helpFloatFavorites: "翻訳 UI のモデル一覧は「設定 → API プロバイダ」でお気に入りに星を付けたモデルを優先（検索可能なピッカー ★）。そのプロバイダにお気に入りがない場合、現在選択中のモデルが表示されます。",
            .helpFloatDoubleClick: "原文（ソース）テキストエリアをダブルクリックするとクリップボードから貼り付けて即座に翻訳 — 自分でテキストをコピーした後に便利。",
            .helpFloatEscape: "Esc または閉じるボタンでフローティングパネルを閉じます。閉じても Bolabol は終了しません。",
            .helpCloudTitle: "クラウド API プロバイダ",
            .helpCloudIntro: "「設定 → API プロバイダ」は推敲と翻訳用のクラウド LLM を設定 — Whisper 音声認識用ではありません。レイアウト：上部にプロバイダドロップダウン、詳細カード、そして使用統計。",
            .helpCloudProviders: "ドロップダウン順：Google Gemini → OpenAI → Qwen → OpenRouter → Custom。（Anthropic は現在の UI に表示されません。）有効バッジが推敲に使われるエンジン印。",
            .helpCloudConfigure: "プロバイダを選択、キーを入力、「モデルを参照」を開き（検索可能なシート）、テキストモデルを選び、「使用」で推敲。「API キーを取得」は利用可能な場合プロバイダのコンソールを開きます。モデルチップはコンテキスト長と、利用可能な場合入出力価格を表示。",
            .helpCloudKeys: "複数 API キー：各プロバイダは最大 10 個のキーを保存可（キーを追加）。目のアイコンでキーを表示/非表示。最初の非空キーがリクエストに使われ；追加はローテーションや個人/仕事キーの分離に役立ちます。",
            .helpCloudFavorites: "モデルピッカーでモデルをお気に入りに星付け（★）。お気に入りは上部に並び、フローティング翻訳ウィンドウのモデルメニューで優先されます。お気に入りはこの Mac に保存。",
            .helpCloudOpenRouter: "OpenRouter：ライブアカウント残高（色分けの残り USD）、コンテキストと $/M トークン価格の検索可能なカタログ、更新コントロール。長いセッション前に残高を確認。",
            .helpCloudBudget: "OpenRouter 予算スライダは設定内の個人的なソフトリミット補助（いくら使うかの視覚的ガイド）— それ自体では API を遮断しません。実際の残高バナーで残りクレジットを確認。",
            .helpCloudCustom: "Custom：任意の OpenAI 互換ベース URL + キー（プロキシ、セルフホスト、ベンダーエンドポイント）。キーと URL 設定後、モデルはそのエンドポイントから読み込まれます。",
            .helpCloudStats: "API プロバイダ下部の使用統計：選択中モデルの最終トランザクションのトークンと合計。統計をリセットでそれらのカウンタをクリア。",
            .helpPolishTitle: "推敲、MLX、プロンプト",
            .helpPolishIntro: "文字起こしは音声をテキストに変換。推敲はそのテキストを書き直します。異なるモデルと設定を使用。",
            .helpPolishEngines: "エンジン：推敲無効（Raw のみ）· クイックローカルクリーンアップ（ルール、LLM なし、完全オフライン）· ローカル MLX モデル · API プロバイダからのクラウドプロバイダ。メインメモのツールバーと設定の両方からプロバイダ/モデルを切替可能。",
            .helpPolishMLX: "「設定 → 推敲」：カタログモデルをダウンロードまたは「ローカルモデルをスキャン」でディスク上を検索。非推論 instruct モデルを推奨；推論/思考モデルは遅く、思考の連鎖をメモに漏らす可能性。",
            .helpPolishPrompts: "「設定 → プロンプト」：バリアント 1、バリアント 2、Markdown を編集。すべてのプロンプトは \(PromptTemplate.transcriptionPlaceholder) プレースホルダを保持する必要。リセットで内蔵テンプレートを復元。",
            .helpMoreTitle: "用語集、読み込み、翻訳",
            .helpMoreGlossary: "用語集は推奨する綴りと用語のローカル辞書（ソース → 翻訳、バリアント、カテゴリ）。Whisper を再学習させず、認識/翻訳後にテキストを書き直します。有効化、エントリ追加、またはメモでテキストを選択 → 用語集に追加。クリア前に JSON を書き出し。ここの自動翻訳言語はホットキー言語が自動のとき HUD 文字モードを支えます。",
            .helpMoreImport: "音声を読み込むかファイルをウィンドウにドロップして、有効な音声モデルで文字起こし済みメモを作成。",
            .helpMoreTranslate: "メインウィンドウから、または Option+1 フローティングパネルで翻訳（Option+2 は結果のみ表示）：選択 / クリップボード / ライブ音声入力 → プロバイダ + モデル + ターゲット言語。翻訳は意図的に言語を変更；バリアント 1/2 は同じ言語を維持。ターゲットが英語でないとき HUD 文字モードは翻訳エンジンを使用。",
            .helpPrivacyTitle: "プライバシー、ストレージ、診断",
            .helpPrivacyLocal: "Whisper 文字起こし、クイックローカルクリーンアップ、ローカル MLX 推敲はこの Mac に留まります。録音は App のローカルデータフォルダに保存されます。",
            .helpPrivacyCloud: "クラウド推敲とクラウド翻訳はテキスト（とプロンプト）を選択中のプロバイダに送信します。メモを非公開に保つ必要がある場合はローカルエンジンを使ってください。",
            .helpPrivacyClear: "すべてクリアはすべてのメモを永久に削除し、中断されたセッションが残した孤立音声を含め録音フォルダを空にします。内容が大事な場合は先に書き出してください。",
            .helpPrivacyLogs: "一般 → システムログを書き出すで診断ファイルを取得。デバッグログレベルはトラブルシューティング時のみ使用。テーマ、UI スケール、HUD サイズ/サウンド、表示言語も一般の下。",
            .helpTipsTitle: "よくあるヒント",
            .helpTipEnglish: "他の言語から英語出力が必要？多言語 Whisper + HUD 文字 E（または文字起こし言語 = English）+ Large v3 Full。",
            .helpTipNonEnglish: "スペイン語/ロシア語/… 出力が必要？その言語をホットキーで設定し、HUD を文字に切り替え、クラウドまたは MLX 推敲エンジンを有効に保ちます。",
            .helpTipDisk: "ディスクがモデルや録音でいっぱい？ローカルモデルで未使用の Whisper モデルを削除；メモと残存 .caf ファイルを消去する意図があるときのみすべてクリアを使ってください。",
            .helpTipStuck: "ホットキーや入力が固まる？ホットキーが有効、メインウィンドウでマイクが動作、入力モードにアクセシビリティが許可されていることを確認し、ステータスを更新を試してください。それでも失敗すればログを書き出し。",
            .helpWelcomeTitle: "Bolabol ヘルプ",
            .helpWelcomeBody: "Mac のどこからでも音声入力。音声は Whisper でデバイス上で文字起こしされ、テキストは Raw のまま、クリーンアップ、または書き直しができ、その後コピーまたは使用中の App に入力できます。",
            .helpQuickStart: "ここから始めましょう（最初の 5 分）",
            .helpRecordStep: "他の App をクリック → ホットキー（デフォルト Option+S）→ 話す → もう一度押して停止。赤 HUD = 録音中、緑 = 処理中。",
            .helpVariantsStep: "Raw は文字起こし。バリアント 1 は軽いクリーンアップ。バリアント 2 はより強い書き直し。Markdown は推敲済みテキストを構造化。",
            .helpCopyStep: "現在のタブをコピー、サイドバーからすべてのメモをコピー、またはホットキーのクリップボード / アクティブな App に入力で渡します。",
            .helpRecordingTitle: "オーバーレイ HUD",
            .helpHUDStep: "HUD：[A|文字] 波形 [R|1|2]。左をタップ A↔E、右をタップ R→1→2。どこへでもドラッグ；サイズ/サウンドは一般 → オーバーレイ HUD。",
            .helpOfflineTranscription: "ローカル文字起こしモデル",
            .helpOfflineModelStep: "設定 → ローカルモデル：WhisperKit モデルをダウンロード。品質と英語翻訳には Large v3 Full を推奨。",
            .helpOfflineActivateStep: "ダウンロード済みモデルで「使用」を押します。削除でディスク容量を解放。フォールバック：Apple Speech。",
            .helpImportTitle: "読み込みと翻訳",
            .helpImportStep: "音声を読み込むかファイルをウィンドウにドラッグして新規メモとして文字起こし。",
            .helpTranslateStep: "翻訳モーダル：選択、クリップボード、または短い録音 → プロバイダ + ターゲット言語。",
            .helpPolishingProviders: "推敲エンジン",
            .helpPolishingProviderStep: "無効、クイックローカルクリーンアップ、ローカル MLX、または API プロバイダからのクラウド API プロバイダ。",
            .helpPromptsStep: "設定 → プロンプトでバリアント 1、バリアント 2、Markdown。文字起こしプレースホルダを保持。",
            .helpHotkeyStep: "設定 → ホットキー：Option+S を有効化、ターゲットとモードを選択、App への入力のためだけにアクセシビリティを許可。",
