            .additionalSameAsPrimary: "기본 언어와 동일",
            .languagePairEngineNote: "Parakeet과 Whisper는 여전히 기본적으로 음성을 자동 감지합니다. 두 언어는 기본값이며 HUD에서 언어를 전환할 때 사용됩니다.",
            .helpBilingualTitle: "내 언어",
            .helpBilingualIntro: "Bolabol은 두 가지 언어로 작동합니다. 기본 언어(평소에 받아쓰기로 사용하는 언어)와 추가 언어(자주 사용하는 두 번째 언어)입니다. 이 방식은 항상 특정 언어로 강제 출력하는 모델이 아닙니다. 추가 언어는 빠른 전환을 위한 두 번째 언어일 뿐입니다.",
            .helpBilingualPrimary: "기본 언어 = 평소 받아쓰기 언어입니다. 음성 인식과 Raw 출력의 기본값은 이 언어입니다. 기본 언어로 말할 때 HUD는 A(자동 감지)를 표시합니다.",
            .helpBilingualAdditional: "추가 언어 = 자주 사용하는 두 번째 언어입니다. HUD에서 왼쪽 버튼을 눌러 A에서 이 언어를 나타내는 글자(E, S, R, F, C, G, …)로 전환하면 해당 언어로 강제 출력됩니다. 다시 누르면 A로 돌아갑니다.",
            .helpBilingualNotAlwaysOutput: "중요: 추가 언어는 항상 특정 언어로 강제 출력하는 설정이 아닙니다. 어떤 언어로든 받아쓰기를 할 수 있으며, HUD의 글자는 이번 세션의 출력 언어를 빠르게 고를 수 있게 해 줄 뿐입니다. 대상을 강제하지 않는 한 Raw 출력은 실제로 말한 언어를 그대로 따릅니다.",
            .helpBilingualWhere: "초기 설정에서 두 언어를 설정하거나, 언제든지 설정 → 단축키 → 내 언어에서 변경할 수 있습니다. 이 언어 쌍은 HUD 글자 선택에도 사용됩니다.",
