            .helpHeroTitle: "مساعدة Bolabol",
            .helpHeroSubtitle: "أملِ في أي مكان على Mac. يُنسخ الكلام على الجهاز باستخدام Whisper؛ يمكن أن يبقى النص خامًا، أو يُنظَّف، أو يُعاد كتابته — ثم يُنسخ أو يُكتب في التطبيق الذي كنت تستخدمه.",
            .helpStartTitle: "ابدأ هنا (أول 5 دقائق)",
            .helpStart1: "اسمح بالميكروفون عندما يطلب macOS ذلك. بدونه لا يمكن بدء التسجيل.",
            .helpStart2: "افتح الإعدادات → النماذج المحلية، نزّل نموذج Whisper (Large v3 Full هو الخيار الأفضل عمومًا)، ثم اضغط «استخدام».",
            .helpStart3: "افتح الإعدادات → مفتاح الاختصار وشغّل مفاتيح الاختصار. الأساسي (الافتراضي Option+S) هو الإملاء. يفتح مفتاح اختصار نافذة الترجمة (الافتراضي Option+1) لوحة الترجمة العائمة الكاملة؛ تفتح الترجمة السريعة (الافتراضي Option+2) النتيجة فقط؛ يفتح فتح الإعدادات (الافتراضي Option+~) التفضيلات. للإملاء اختر الهدف (Raw / المتغيّر 1 / المتغيّر 2) والوضع (الحافظة أو الكتابة في التطبيق النشط).",
            .helpStart4: "اختياري: في مزوّدو API أضف مفتاح سحابة (يمكنك تخزين عدة مفاتيح لكل مزوّد)، اختر نموذجًا، علّم المفضلة بنجمة، ثم «استخدام» للتنقيح — أو ثبّت نموذج MLX محليًا. بدون محرك تنقيح/ترجمة، لن يحسّن المتغيّر 1/2 واللغة غير الإنجليزية القسرية النص.",
            .helpStart5: "الإملاء: ركّز على أي تطبيق → Option+S → تحدّث → Option+S مرة أخرى (HUD أحمر = تسجيل، أخضر = معالجة). الترجمة الفورية: حدّد نصًا في مكان آخر → Option+1 → تلتقط اللوحة العائمة التحديد/الحافظة وتترجم (Option+2 يعرض النتيجة فقط).",
            .helpModesTitle: "أربع طرق للعمل",
            .helpModeWindowTitle: "النافذة الرئيسية",
            .helpModeWindowBody: "دفتر للملاحظات: سجّل أو استورد الصوت، راجع Raw / المتغيّر 1 / المتغيّر 2، نقّح، ترجم، وانسخ. مثالي عندما تريد التحرير والاحتفاظ بالسجل.",
            .helpModeHotkeyTitle: "مفتاح الاختصار + HUD المتراكب",
            .helpModeHotkeyBody: "ابقَ داخل تطبيق آخر. يسجّل مفتاح الاختصار الأساسي (Option+S) باستخدام HUD العائم: وضع اللغة (A / حرف) وهدف الإخراج (R / 1 / 2). أثناء ظهور HUD، مرّر للتبديل بين مزوّدي التحسين، وانقر بزر الماوس الأيمن على مزوّد لاختيار نموذج محدّد. لا يسرق تركيز لوحة المفاتيح أثناء الإملاء.",
            .helpModeFloatTitle: "نافذة الترجمة العائمة",
            .helpModeFloatBody: "يفتح مفتاح اختصار نافذة الترجمة (الافتراضي Option+1) لوحة ترجمة دائمًا في المقدمة. تلتقط النص المحدد من التطبيق النشط (عبر Command-C سريع)، تملأ الأصل، ويمكن أن تترجم فورًا. مفيدة لتغيير اللغة دون إملاء كامل.",
            .helpWindowTitle: "النافذة الرئيسية",
            .helpWindowBody: "يسار: قائمة الملاحظات. يمين: الملاحظة المحددة — معلومات الصوت، قوائم مزوّد/نموذج التنقيح، علامات النص، وشريط الإجراءات.",
            .helpWindowNotes: "الشريط الجانبي: حدّد ملاحظة، نسخ الكل، أو مسح الكل (دائم: يحذف كل ملاحظة وملفات التسجيل المتبقية على القرص).",
            .helpWindowTabs: "علامات التبويب: Raw = النسخ الخالص. المتغيّر 1 = تنظيف خفيف (الحشو، التكرار). المتغيّر 2 = إعادة كتابة أقوى للوضوح. استخدم إجراء Markdown على علامة منقّحة لهيكلة النص. تبدّل فتحات الموجّه D/1/2/3/4 الموجّه المخصص النشط لذلك المتغيّر.",
            .helpWindowActions: "الشريط السفلي: تسجيل / إيقاف، ملاحظة فارغة، استيراد صوت (أو اسحب ملفًا إلى النافذة)، ترجمة، تنقيح، نسخ. تفتح الإعدادات التفضيلات.",
            .helpWindowPolishingMenus: "فوق المحرر يمكنك تبديل مزوّد التنقيح (معطّل / تنظيف سريع / MLX محلي / سحابة) ونموذج التنقيح (نماذج مزوّد السحابة المحدد، أو بطاقات MLX المحلية). يطابق هذا الإعدادات → مزوّدو API / التنقيح دون مغادرة الملاحظة.",
            .helpHUDTitle: "HUD المتراكب (الكبسولة العائمة)",
            .helpHUDIntro: "عند الضغط على مفتاح الاختصار العام، تظهر كبسولة عائمة صغيرة فوق كل تطبيق. ليست نافذة عادية: تبقى في المقدمة، لا تسرق تركيز لوحة المفاتيح، وتعرض الحالة فقط — وليس النسخ الكامل.",
            .helpHUDAnatomy: "التخطيط يسار → يمين: (1) زر اللغة · (2) شكل الموجة الحي في المنتصف · (3) زر هدف الإخراج. على شاشتك غالبًا تبدو مثل [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "يتحول شكل الموجة الأوسط إلى الأحمر أثناء تسجيل الميكروفون. تحدّث وهو أحمر.",
            .helpHUDColorGreen: "بعد الإيقاف (مفتاح الاختصار مرة أخرى)، يتحول شكل الموجة إلى الأخضر: ينسخ Bolabol، وينقّح إذا لزم، ويسلّم النص. انتظر حتى يختفي HUD.",
            .helpHUDLeftTitle: "الزر الأيسر — وضع اللغة (A ↔ حرف)",
            .helpHUDLeftA: "A = Auto. يكتشف Bolabol تلقائيًا اللغة التي تحدثت بها. يبقى النسخ بتلك اللغة (لغتك الأساسية افتراضيًا). لا ترجمة مفروضة — استخدم هذا عندما تريد مخرجات Raw بلغة حديثك.",
            .helpHUDLeftLetter: "حرف بدلًا من A يعني «فرض لغة المخرجات». الحرف هو أول حرف من الاسم الإنجليزي لتلك اللغة: E = English، S = Spanish، R = Russian، F = French، C = Chinese، G = German، وهكذا. افتراضيًا، الحرف هو لغتك الإضافية من الإعدادات → مفتاح الاختصار → لغاتك. إذا ضُبط مفتاح الاختصار → لغة النسخ على لغة محددة، تصبح تلك اللغة هي الحرف بدلًا منها.",
            .helpHUDLeftTap: "انقر الزر الأيسر مرة واحدة للتبديل من A → حرف (فرض المخرجات على اللغة الإضافية)، وانقر مجددًا للتبديل من حرف → A (كشف تلقائي). يُتذكّر الاختيار للجلسة التالية.",
            .helpHUDRightTitle: "الزر الأيمن — هدف الإخراج (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. يسلّم النسخ البسيط بدون تنقيح المتغيّر 1 / المتغيّر 2. أسرع مسار؛ يمكنه مع ذلك استخدام ترجمة Whisper إلى الإنجليزية عندما يكون الزر الأيسر E.",
            .helpHUDRightCycle: "1 = المتغيّر 1 (تنظيف خفيف). 2 = المتغيّر 2 (إعادة كتابة أقوى). تحتاج هذه إلى محرك تنقيح نشط (سحابة أو MLX محلي). اختيار 1 أو 2 يعيد تشغيل التنقيح إذا كان معطّلًا.",
            .helpHUDRightTap: "انقر الزر الأيمن للتنقّل R → 1 → 2 → R. يصبح الاختيار الهدف الافتراضي الجديد في إعدادات مفتاح الاختصار للإملاءات المستقبلية.",
            .helpHUDControlLanguage: "يسار: A = كشف تلقائي (النسخ بلغة الحديث). حرف (E، S، R، …) = فرض المخرجات على تلك اللغة (الافتراضي = اللغة الإضافية). انقر للتبديل A ↔ حرف.",
            .helpHUDControlTarget: "يمين: R = نسخ Raw، 1 = المتغيّر 1، 2 = المتغيّر 2. انقر للتنقّل R → 1 → 2 → R.",
            .helpHUDDrag: "السحب: انقر مع الاستمرار في أي مكان على الكبسولة (ليس الأزرار فقط) وانقلها إلى أي مكان على أي شاشة. ضعها قرب الزاوية، فوق الـ dock، أو بجانب التطبيق الذي تكتب فيه — أينما شئت.",
            .helpHUDSize: "الحجم والشفافية: الإعدادات → عام → HUD المتراكب. يقيس منزلق الحجم الكبسولة كلها (وعدد أشرطة الطيف التي تراها). تخفّف الشفافية خلفية الزجاج ليظهر محتوى سطح المكتب أكثر أو أقل.",
            .helpHUDSound: "الأصوات: نفس القسم عام → HUD المتراكب. بدّل «تشغيل الصوت عند البدء/الانتهاء»، اضبط مستوى الصوت، واستخدم اختبار أصوات HUD للمعاينة دون تسجيل. تُشغَّل الإشارات عند بدء التسجيل وعند انتهاء المعالجة.",
            .helpHUDSettingsPath: "كل مظهر HUD تحت الإعدادات → عام → HUD المتراكب (الحجم، الشفافية، الصوت، المستوى). يُحفظ الموضع تلقائيًا بعد السحب.",
            .helpHUDPosition: "بعد سحب HUD، يتذكّر Bolabol ذلك الموضع ويعيد الفتح هناك في المرة التالية.",
            .helpHUDDuration: "لا حد اصطناعي قصير لمدة كلامك. واصل التحدّث بينما شكل الموجة أحمر؛ اضغط مفتاح الاختصار مرة أخرى عند الانتهاء.",
            .helpLangTitle: "أوضاع اللغة بالتفصيل",
            .helpLangIntro: "التحكم في اللغة هو الزر الأيسر لـ HUD (A ↔ حرف) إضافة إلى الإعدادات → مفتاح الاختصار → لغاتك (الأساسية + الإضافية). يعتمد حرف HUD افتراضيًا على لغتك الإضافية. ويعملان معًا.",
            .helpLangAuto: "A (تلقائي): يبقى النسخ باللغة التي تحدثت بها (لغتك الأساسية افتراضيًا). مثالي للملاحظات بلغتك المعتادة دون فرض لغة على المخرجات.",
            .helpLangForced: "حرف (هدف قسري): بعد التعرف على الكلام، يمكن لـ Bolabol تقديم النسخ بلغتك الإضافية (أو لغة أخرى تختارها). تحدث بأي لغة؛ وانقر الزر الأيسر في HUD للتبديل من A إلى الحرف (E، S، R، F، C، G…) لفرض اللغة على المخرجات. اللغة الإضافية من الإعدادات → مفتاح الاختصار → لغاتك هي اختيار الحرف الافتراضي.",
            .helpLangEnglishNote: "الإنجليزية القسرية + Whisper متعدد اللغات: يستخدم Raw الترجمة المدمجة إلى الإنجليزية في Whisper على الجهاز (سريعة). فضّل Large v3 Full للجودة؛ أما Turbo فهو أخف لكنه أقل موثوقية مع الكلام الطويل أو المختلط. ينطبق هذا عندما يكون حرف HUD هو E (لغتك الإضافية أو هدف تختاره).",
            .helpLangOtherNote: "أي إخراج قسري بغير الإنجليزية (حرف ≠ E) يحتاج دائمًا إلى LLM بعد Whisper (سحابة أو MLX محلي). بدون محرك تنقيح نشط، لا يمكن للإسبانية/الروسية/… القسرية تحويل اللغة.",
            .helpLangWhere: "يعتمد حرف HUD (الهدف القسري) افتراضيًا على لغتك الإضافية من الإعدادات → مفتاح الاختصار → لغاتك. إذا ضُبطت لغة مفتاح الاختصار على لغة محددة، تصبح تلك اللغة هي الحرف. إذا كان مفتاح الاختصار على Auto، يتراجع الحرف إلى المسرد → Auto Translation Language، ثم إلى الإنجليزية. غيّر لغتيك من الإعدادات → مفتاح الاختصار → لغاتك.",
            .helpModelsTitle: "نماذج النسخ المحلية",
            .helpModelsIntro: "تدير الإعدادات → النماذج المحلية نماذج WhisperKit Core ML التي تحوّل الصوت إلى نص على Apple Silicon. هذا منفصل عن نماذج التنقيح.",
            .helpModelsCatalog: "الإنجليزية فقط (Small/Medium .en): سريع عندما تتحدث الإنجليزية فقط. Small/Medium متعدد اللغات: متعدد اللغات أخف. Large v3 Turbo (~1.6 غيغابايت): نموذج كبير سريع. Large v3 Full (~3 غيغابايت، أفضل جودة): الافتراضي الموصى به للدقة والترجمة إلى الإنجليزية.",
            .helpModelsRecommend: "للغات المختلطة والإنجليزية القسرية (حرف HUD E)، استخدم نموذجًا متعدد اللغات — مثاليًا Large v3 Full. لا تستطيع نماذج الإنجليزية فقط ترجمة اللغات الأخرى إلى الإنجليزية أصليًا.",
            .helpModelsUse: "تنزيل → استخدام (واحد نشط فقط). يحذف «حذف» الملفات من هذا الـ Mac. لا يوجد بديل Apple Speech — اختر Whisper المحلي (مع نموذج منزّل) أو Cloud · Google Gemini (مطلوب مفتاح Google API).",
            .helpHotkeyTitle: "إعدادات مفتاح الاختصار",
            .helpHotkeyIntro: "تفعّل الإعدادات → مفتاح الاختصار أربعة اختصارات عامة مستقلة. شغّل «تفعيل مفتاح الاختصار» قبل أن يعمل أي منها.",
            .helpHotkeyPrimary: "الأساسي (الافتراضي Option+S (⌥S)): يبدأ/يوقف الإملاء في HUD المتراكب. الضغطة الأولى تسجّل (أحمر)، الثانية تعالج (أخضر) وتسلّم Raw / المتغيّر 1 / المتغيّر 2.",
            .helpHotkeyPushToTalk: "Push-to-Talk (اختياري): شغِّل وضع Push-to-Talk من الإعدادات → مفتاح الاختصار لتضغط باستمرار على مفتاح الاختصار الأساسي أثناء التسجيل، ثم أفلته ليتم النسخ والتحسين تلقائيًا — بدلاً من الضغط مرة للبدء ومرة أخرى للإيقاف.",
            .helpHotkeySecondary: "نافذة الترجمة (الافتراضي Option+1): تفتح لوحة الترجمة العائمة الكاملة. ليس مفتاح تسجيل — يلتقط التحديد/الحافظة ويترجم. يعيد سهم إعادة التعيين Option+1.",
            .helpHotkeyTertiary: "الترجمة السريعة (الافتراضي Option+2): تفتح نافذة صغيرة للقراءة فقط بها نتيجة الترجمة فقط. اضغط مفتاح الاختصار مرة أخرى أو Escape لإغلاقها.",
            .helpHotkeySettings: "فتح الإعدادات (الافتراضي Option+~): يفتح نافذة إعدادات Bolabol من أي مكان، لتبديل النماذج أو اللغات دون مغادرة تطبيقك.",
            .helpModeQuickTitle: "نافذة الترجمة السريعة",
            .helpModeQuickBody: "يفتح مفتاح الاختصار الثالث (الافتراضي Option+2) نافذة صغيرة دائمًا في المقدمة تعرض نتيجة الترجمة فقط — بدون لوحة مصدر، بدون أزرار. اقرأها ثم اضغط Escape للإغلاق. للتحرير أو إعادة الترجمة، استخدم نافذة الترجمة العائمة الكاملة بدلًا من ذلك.",
            .helpFloatQuick: "نافذتا ترجمة: نافذة الترجمة العائمة (Option+1) هي اللوحة الكاملة مع النص المصدر وقوائم المزوّد/النموذج وعناصر التحكم؛ الترجمة السريعة (Option+2) نافذة صغيرة للقراءة فقط تعرض النتيجة فقط. استخدم الترجمة السريعة عندما تحتاج فقط لقراءة ترجمة.",
            .helpHotkeyTarget: "هدف الإملاء: أي نص يُسلّم بعد التسجيل — Raw أو المتغيّر 1 أو المتغيّر 2. نفس اختيار الزر الأيمن لـ HUD (R / 1 / 2).",
            .helpHotkeyMode: "وضع الإملاء: تنسخ الحافظة النتيجة لتلصقها؛ تدرج الكتابة في التطبيق النشط في الحقل الذي كان مركّزًا عند بدء التسجيل.",
            .helpHotkeyAccess: "تحتاج الكتابة في التطبيق النشط إلى إذن إمكانية الوصول (نفس صفحة الإعدادات). لا يحتاج وضع الحافظة ونافذة الترجمة العائمة إلى إمكانية الوصول للصق في اللوحة — لكن التقاط النص من التطبيقات الأخرى عبر Command-C يعمل بشكل أفضل عندما يكون التطبيق موثوقًا.",
            .helpFloatTitle: "نافذة الترجمة العائمة",
            .helpFloatIntro: "لوحة أدوات قابلة لتغيير الحجم، دائمًا في المقدمة (Bolabol Translation)، منفصلة عن الدفتر الرئيسي. مثالية لتغيير اللغة سريعًا بينما تبقى في المتصفح أو البريد أو الدردشة.",
            .helpFloatHotkey: "افتحها بمفتاح اختصار نافذة الترجمة (الإعدادات → مفتاح الاختصار → نافذة الترجمة، الافتراضي Option+1). يمكنك أيضًا فتح «ترجمة» من الشريط السفلي للنافذة الرئيسية؛ تشارك اللوحة العائمة نفس الواجهة.",
            .helpFloatCapture: "عند الفتح، يرسل Bolabol بإيجاز Command-C إلى التطبيق الأمامي لنسخ أي تحديد، ثم يفضّل تحديد الملاحظة إذا كنت داخل Bolabol، وإلا نص الحافظة. إذا التُقط شيء وهُيّئ مزوّد ترجمة، تبدأ الترجمة تلقائيًا.",
            .helpFloatPanel: "داخل اللوحة: اختر المزوّد والنموذج، عيّن لغة الهدف، حرّر الأصل، شغّل ترجمة / ترجمة مرة أخرى، أو سجّل مقطعًا قصيرًا للترجمة. تبقى اللوحة عائمة فوق التطبيقات الأخرى وقابلة لتغيير الحجم.",
            .helpFloatFavorites: "تفضّل قائمة النماذج في واجهة الترجمة النماذج التي علّمتها كمفضلة في الإعدادات → مزوّدو API (منتقي قابل للبحث ★). إذا لم يكن لديك مفضلة لذلك المزوّد، يُعرض النموذج المحدد حاليًا.",
            .helpFloatDoubleClick: "انقر نقرًا مزدوجًا على منطقة نص الأصل (المصدر) للصق من الحافظة والترجمة فورًا — مفيد بعد نسخ النص بنفسك.",
            .helpFloatEscape: "اضغط Escape أو زر الإغلاق لإغلاق اللوحة العائمة. الإغلاق لا يُنهي Bolabol.",
            .helpCloudTitle: "مزوّدو API السحابيون",
            .helpCloudIntro: "تهيّئ الإعدادات → مزوّدو API نماذج LLM السحابية للتنقيح والترجمة — وليس للتعرف على كلام Whisper. التخطيط: قائمة المزوّد المنسدلة في الأعلى، بطاقة التفاصيل، ثم إحصائيات الاستخدام.",
            .helpCloudProviders: "ترتيب القائمة المنسدلة: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (لا يظهر Anthropic في الواجهة الحالية.) تميّز شارة «نشط» المحرك المستخدم للتنقيح.",
            .helpCloudConfigure: "اختر مزوّدًا، أدخل المفاتيح، افتح تصفّح النماذج (ورقة قابلة للبحث)، اختر نموذج نص، ثم «استخدام» للتنقيح. يفتح «الحصول على مفتاح API» وحدة تحكم المزوّد عند توفرها. تعرض شرائح النموذج طول السياق، وعند توفرها، أسعار الإدخال/الإخراج.",
            .helpCloudKeys: "مفاتيح API متعددة: يمكن لكل مزوّد تخزين حتى 10 مفاتيح (إضافة مفتاح). يظهر/يخفي أيقونة العين المفتاح. يُستخدم أول مفتاح غير فارغ للطلبات؛ تساعد المفاتيح الإضافية في التدوير أو فصل المفاتيح الشخصية عن العملية.",
            .helpCloudFavorites: "في منتقي النماذج، علّم النماذج كمفضلة (★). تُرتَّب المفضلة في الأعلى وتُفضَّل في قائمة نماذج نافذة الترجمة العائمة. تُخزَّن المفضلة على هذا الـ Mac.",
            .helpCloudOpenRouter: "OpenRouter: رصيد الحساب المباشر (دولارات متبقية بترميز لوني)، كتالوج قابل للبحث مع السياق وأسعار الرموز $/M، وتحكم التحديث. تحقق من الرصيد قبل الجلسات الطويلة.",
            .helpCloudBudget: "منزلق ميزانية OpenRouter هو مساعد حد شخصي مرن في الإعدادات (دليل مرئي لكم تنوي إنفاقه) — لا يقطع API بنفسه. راقب لافتة الرصيد الحقيقي للرصيد المتبقي.",
            .helpCloudCustom: "Custom: أي عنوان URL أساسي متوافق مع OpenAI + مفتاح (وكلاء، ذاتي الاستضافة، أو نقاط نهاية بائع). تُحمَّل النماذج من نقطة النهاية تلك بعد تعيين المفتاح والعنوان.",
            .helpCloudStats: "إحصائيات الاستخدام أسفل مزوّدو API: رموز آخر معاملة والإجماليات للنموذج المحدد. تمسح إعادة تعيين الإحصائيات تلك العدّادات.",
            .helpPolishTitle: "التنقيح وMLX والموجّهات",
            .helpPolishIntro: "يحوّل النسخ الكلام إلى نص. يعيد التنقيح كتابة ذلك النص. يستخدمان نماذج وإعدادات مختلفة.",
            .helpPolishEngines: "المحركات: التنقيح معطّل (Raw فقط) · تنظيف محلي سريع (قواعد، بدون LLM، دون اتصال بالكامل) · نموذج MLX محلي · مزوّد سحابي من مزوّدو API. يمكنك تبديل المزوّد/النموذج من شريط أدوات الملاحظة الرئيسية وكذلك من الإعدادات.",
            .helpPolishMLX: "الإعدادات → التنقيح: نزّل نماذج الكتالوج أو ابحث عن النماذج المحلية على القرص. فضّل نماذج instruct غير الاستدلالية؛ نماذج الاستدلال/التفكير أبطأ وقد تسرّب سلسلة التفكير إلى الملاحظة.",
            .helpPolishPrompts: "الإعدادات → الموجّهات: حرّر المتغيّر 1 والمتغيّر 2 وMarkdown. يجب أن يحتفظ كل موجّه بالعنصر النائب \(PromptTemplate.transcriptionPlaceholder). تعيد إعادة التعيين القالب المدمج.",
            .helpMoreTitle: "المسرد والاستيراد والترجمة",
            .helpMoreGlossary: "المسرد قاموس محلي للإملاءات والمصطلحات المفضلة (المصدر → الترجمة، المتغيّرات، الفئات). لا يعيد تدريب Whisper؛ بل يعيد كتابة النص بعد التعرف/الترجمة. فعّله، أضف إدخالات، أو حدّد نصًا في ملاحظة → إضافة إلى المسرد. صدّر JSON قبل المسح. تدعم لغة الترجمة التلقائية هنا وضع حرف HUD عندما تكون لغة مفتاح الاختصار تلقائية.",
            .helpMoreImport: "استورد صوتًا أو أسقط ملفًا على النافذة لإنشاء ملاحظة منسوخة بالنموذج الصوتي النشط.",
            .helpMoreTranslate: "ترجم من النافذة الرئيسية أو عبر اللوحة العائمة Option+1 (يعرض Option+2 النتيجة فقط): التحديد / الحافظة / الإملاء الحي → مزوّد + نموذج + لغة الهدف. تغيّر الترجمة اللغة عمدًا؛ يحافظ المتغيّر 1/2 على نفس اللغة. يستخدم وضع حرف HUD محرك الترجمة عندما لا يكون الهدف الإنجليزية.",
            .helpPrivacyTitle: "الخصوصية والتخزين والتشخيص",
            .helpPrivacyLocal: "يبقى نسخ Whisper والتنظيف المحلي السريع وتنقيح MLX المحلي على هذا الـ Mac. تُخزَّن التسجيلات في مجلدات بيانات التطبيق المحلية.",
            .helpPrivacyCloud: "يرسل التنقيح السحابي والترجمة السحابية نصك (والموجّهات) إلى المزوّد المحدد. استخدم المحركات المحلية عندما يجب أن تبقى الملاحظات خاصة.",
            .helpPrivacyClear: "يمسح «مسح الكل» كل الملاحظات نهائيًا ويفرغ مجلد التسجيلات، بما في ذلك الصوت اليتيم الذي تركته الجلسات المقطوعة. صدّر أولًا إذا كان المحتوى يهمك.",
            .helpPrivacyLogs: "عام → تصدير سجلات النظام لملف تشخيصي. استخدم مستوى سجل التصحيح فقط أثناء استكشاف الأخطاء. المظهر ومقياس الواجهة وحجم/أصوات HUD ولغة الواجهة أيضًا تحت عام.",
            .helpTipsTitle: "نصائح شائعة",
            .helpTipEnglish: "تحتاج إخراجًا بالإنجليزية من لغات أخرى؟ Whisper متعدد اللغات + حرف HUD E (أو لغة النسخ = English) + Large v3 Full.",
            .helpTipNonEnglish: "تحتاج إخراجًا بالإسبانية/الروسية/…؟ عيّن تلك اللغة تحت مفتاح الاختصار، بدّل HUD إلى الحرف، وأبقِ محرك تنقيح سحابي أو MLX نشطًا.",
            .helpTipDisk: "القرص ممتلئ بالنماذج أو التسجيلات؟ احذف نماذج Whisper غير المستخدمة في النماذج المحلية؛ استخدم «مسح الكل» فقط عندما تنوي مسح الملاحظات وملفات .caf المتبقية.",
            .helpTipStuck: "مفتاح الاختصار أو الكتابة عالقة؟ تأكّد من تفعيل مفتاح الاختصار، وأن الميكروفون يعمل في النافذة الرئيسية، وأن إمكانية الوصول ممنوحة لوضع الكتابة، ثم جرّب تحديث الحالة. صدّر السجلات إذا استمر الفشل.",
            .helpWelcomeTitle: "مساعدة Bolabol",
            .helpWelcomeBody: "أملِ في أي مكان على Mac. يُنسخ الكلام على الجهاز باستخدام Whisper؛ يمكن أن يبقى النص خامًا، أو يُنظَّف، أو يُعاد كتابته — ثم يُنسخ أو يُكتب في التطبيق الذي كنت تستخدمه.",
            .helpQuickStart: "ابدأ هنا (أول 5 دقائق)",
            .helpRecordStep: "انقر في تطبيق آخر → اضغط مفتاح الاختصار (الافتراضي Option+S) → تحدّث → اضغط مرة أخرى للإيقاف. HUD أحمر = تسجيل، أخضر = معالجة.",
            .helpVariantsStep: "Raw هو النسخ. المتغيّر 1 تنظيف خفيف. المتغيّر 2 إعادة كتابة أقوى. يهيكِل Markdown النص المنقّح.",
            .helpCopyStep: "انسخ علامة التبويب الحالية، نسخ كل الملاحظات من الشريط الجانبي، أو سلّم عبر مفتاح اختصار الحافظة / الكتابة في التطبيق النشط.",
            .helpRecordingTitle: "HUD المتراكب",
            .helpHUDStep: "HUD: [A|حرف] شكل الموجة [R|1|2]. انقر يسارًا A↔E، يمينًا R→1→2. اسحب لأي مكان؛ الحجم/الصوت في عام → HUD المتراكب.",
            .helpOfflineTranscription: "نماذج النسخ المحلية",
            .helpOfflineModelStep: "الإعدادات → النماذج المحلية: نزّل نماذج WhisperKit. فضّل Large v3 Full للجودة والترجمة إلى الإنجليزية.",
            .helpOfflineActivateStep: "اضغط «استخدام» على نموذج منزّل. يحرّر «حذف» مساحة القرص. البديل: Apple Speech.",
            .helpImportTitle: "الاستيراد والترجمة",
            .helpImportStep: "استورد صوتًا أو اسحب ملفًا إلى النافذة لنسخه كملاحظة جديدة.",
            .helpTranslateStep: "نافذة الترجمة: التحديد أو الحافظة أو تسجيل قصير → مزوّد + لغة الهدف.",
            .helpPolishingProviders: "محركات التنقيح",
            .helpPolishingProviderStep: "معطّل، تنظيف محلي سريع، MLX محلي، أو مزوّد API سحابي من مزوّدو API.",
            .helpPromptsStep: "الإعدادات → الموجّهات للمتغيّر 1 والمتغيّر 2 وMarkdown. احتفظ بالعنصر النائب للنسخ.",
            .helpHotkeyStep: "الإعدادات → مفتاح الاختصار: فعّل Option+S، اختر الهدف والوضع، امنح إمكانية الوصول فقط للكتابة في التطبيقات.",
