            .helpBilingualWhere: "حدد لغتيك في الإعداد الأولي، أو غيّرهما في أي وقت من الإعدادات → مفتاح الاختصار → لغاتك. وتتحكم هذه الثنائية أيضًا في خيارات حرف HUD.",
