            .helpBilingualOnboarding: "प्रारंभिक सेटअप आपकी प्राथमिक और अतिरिक्त भाषाएँ पूछता है (योजना §6.1)। अगर आप इसे छोड़ देते हैं, तो डिफ़ॉल्ट आपके सिस्टम लोकेल से लिए जाते हैं।",
