            .helpStart5: "Диктування: сфокусуйте будь-який застосунок → Option+S → говоріть → Option+S ще раз (червоний HUD = запис, зелений = обробка). Миттєвий переклад: виділіть текст в іншому місці → Option+1 → плаваюча панель захоплює виділене/буфер обміну та перекладає (Option+2 показує лише результат).",
            .helpModesTitle: "Чотири способи роботи",
            .helpModeWindowTitle: "Головне вікно",
            .helpModeWindowBody: "Зошит для нотаток: записуйте або імпортуйте аудіо, переглядайте Без обробки / Варіант 1 / Варіант 2, доводьте, перекладайте та копіюйте. Найкраще, коли ви хочете редагувати й зберігати історію.",
            .helpModeHotkeyTitle: "Гаряча клавіша + Оверлей HUD",
            .helpModeHotkeyBody: "Залишайтеся в іншому застосунку. Основна гаряча клавіша (Option+S) записує з плаваючим HUD: мовний режим (A / літера) і ціль виведення (R / 1 / 2). Поки HUD видимий, прокручуйте для перемикання постачальника доводки, а клацніть правою кнопкою по постачальнику, щоб вибрати конкретну модель. Не перехоплює фокус клавіатури під час диктування.",
            .helpModeFloatTitle: "Плаваюче вікно перекладу",
            .helpModeFloatBody: "Гаряча клавіша «Вікно перекладу» (типово Option+1) відкриває панель перекладу, що завжди зверху. Вона захоплює виділений текст з активного застосунку (швидким Command-C), заповнює поле «Оригінал» і може одразу перекласти. Використовуйте, коли потрібна зміна мови без повного диктування.",
            .helpWindowTitle: "Головне вікно",
            .helpWindowBody: "Ліворуч: список нотаток. Праворуч: вибрана нотатка — інформація про аудіо, меню постачальника/моделі доводки, вкладки тексту та панель дій.",
            .helpWindowNotes: "Бічна панель: виберіть нотатку, «Копіювати все» або «Очистити все» (назавжди: видаляє всі нотатки й залишкові файли записів на диску).",
            .helpWindowTabs: "Вкладки: Без обробки = чиста транскрипція. Варіант 1 = легке очищення (слова-паразити, повтори). Варіант 2 = сильніше переписування для ясності. Використовуйте дію Markdown на вкладці доводки, щоб структурувати текст. Слоти промптів D/1/2/3/4 перемикають, який власний промпт активний для цього варіанта.",
            .helpWindowActions: "Нижня панель: Запис / Стоп, Порожня нотатка, Імпорт аудіо (або перетягніть файл у вікно), Переклад, Доводка, Копіювати. Налаштування відкриває параметри.",
            .helpWindowPolishingMenus: "Над редактором можна перемкнути Постачальника доводки (Вимкнено / Швидке очищення / локальна MLX / хмара) і Модель доводки (моделі вибраного хмарного постачальника або локальні MLX-картки). Це відповідає Налаштування → Постачальники API / Доводка без виходу з нотатки.",
            .helpHUDTitle: "Оверлей HUD (плаваюча капсула)",
            .helpHUDIntro: "Коли ви натискаєте глобальну гарячу клавішу, над усіма застосунками з'являється невелика плаваюча капсула. Це не звичайне вікно: воно залишається зверху, не перехоплює фокус клавіатури та показує лише стан — а не повну транскрипцію.",
            .helpHUDAnatomy: "Компонування зліва → праворуч: (1) кнопка мови  ·  (2) жива хвиля посередині  ·  (3) кнопка цілі виведення. На вашому екрані це часто виглядає як  [ A ]  ≈≈≈  [ R ].",
            .helpHUDColorRed: "Середня хвиля стає червоною, поки мікрофон записує. Говоріть, поки вона червона.",
            .helpHUDColorGreen: "Після того як ви зупините (гаряча клавіша ще раз), хвиля стає зеленою: Bolabol транскрибує, за потреби доводить і доставляє текст. Зачекайте, поки HUD сховається.",
            .helpHUDLeftTitle: "Ліва кнопка — режим мови (A ↔ літера)",
            .helpHUDLeftA: "A = Auto. Bolabol автоматично визначає мову, якою ви говорили. Транскрипція залишається цією мовою (за замовчуванням — ваша основна мова). Без примусового перекладу — використовуйте цей режим, коли хочете отримати результат Raw мовою, якою ви говорили.",
            .helpHUDLeftLetter: "Літера замість A означає «примусово задати мову результату». Літера — це перша літера англійської назви мови: E — англійська, S — іспанська, R — російська, F — французька, C — китайська, G — німецька тощо. За замовчуванням літера відповідає вашій додатковій мові з «Налаштування → Гаряча клавіша → Ваші мови». Якщо в «Гаряча клавіша → Мова транскрипції» вибрано конкретну мову, то літерою стане саме вона.",
            .helpHUDLeftTap: "Торкніться лівої кнопки один раз, щоб перемкнути A → літера (примусовий вивід додатковою мовою), і ще раз — щоб повернути літера → A (автовизначення). Цей вибір запам’ятовується до наступної сесії.",
            .helpHUDRightTitle: "Права кнопка — ціль виведення (R → 1 → 2)",
            .helpHUDRightR: "R = Без обробки. Доставляє звичайну транскрипцію без доводки Варіант 1 / Варіант 2. Найшвидший шлях; все ще може використовувати переклад Whisper англійською, коли ліва кнопка — E.",
            .helpHUDRightCycle: "1 = Варіант 1 (легке очищення). 2 = Варіант 2 (сильніше переписування). Для них потрібен активний рушій доводки (хмарний або локальний MLX). Вибір 1 або 2 знову вмикає доводку, якщо її було вимкнено.",
            .helpHUDRightTap: "Натискайте праву кнопку для перемикання R → 1 → 2 → R. Вибір стає новою типовою Ціллю в налаштуваннях гарячої клавіші для майбутніх диктувань.",
            .helpHUDControlLanguage: "Ліва: A = автовизначення (транскрипція мовою, якою ви говорили). Літера (E, S, R, …) = примусовий вивід цією мовою (за замовчуванням — додаткова мова). Торкніться, щоб перемкнути A ↔ літера.",
            .helpHUDControlTarget: "Праворуч: R = транскрипція без обробки, 1 = Варіант 1, 2 = Варіант 2. Натискайте для перемикання R → 1 → 2 → R.",
            .helpHUDDrag: "Перетягування: клацніть й утримуйте будь-де на капсулі (не лише на кнопках) і перемістіть її в будь-яке місце на будь-якому дисплеї. Розмістіть біля кута, над доком або поруч із застосунком, у якому ви вводите — де завгодно.",
            .helpHUDSize: "Розмір і прозорість: Налаштування → Загальні → Оверлей HUD. Повзунок «Розмір» масштабує всю капсулу (і кількість видимих смуг спектра). Прозорість послаблює скляний фон, щоб вміст робочого столу просвічував більше чи менше.",
            .helpHUDSound: "Звуки: той самий розділ Загальні → Оверлей HUD. Перемкніть «Відтворювати звук на початку/завершенні», встановіть гучність звуку та скористайтеся «Тест звуків HUD» для прослуховування без запису. Сигнали лунають на початку запису та після завершення обробки.",
            .helpHUDSettingsPath: "Увесь вигляд HUD міститься в Налаштування → Загальні → Оверлей HUD (розмір, прозорість, звук, гучність). Позиція зберігається автоматично після перетягування.",
            .helpHUDPosition: "Після того як ви перетягнете HUD, Bolabol запам'ятає це місце й наступного разу відкриє там.",
            .helpHUDDuration: "Немає короткого штучного обмеження тривалості мовлення. Говоріть, поки хвиля червона; натисніть гарячу клавішу ще раз, коли завершите.",
            .helpLangTitle: "Докладно про мовні режими",
            .helpLangIntro: "Керування мовою — це ліва кнопка на HUD (A ↔ літера) плюс «Налаштування → Гаряча клавіша → Ваші мови» (основна + додаткова). Літера на HUD за замовчуванням відповідає вашій додатковій мові. Ці два елементи працюють разом.",
            .helpLangAuto: "A (auto): транскрипція залишається мовою, якою ви говорили (за замовчуванням — ваша основна мова). Найкраще для нотаток звичайною мовою, без примусового виводу.",
            .helpLangForced: "Літера (примусова ціль): після розпізнавання мовлення Bolabol може видати транскрипцію вашою додатковою мовою (або іншою обраною мовою). Говоріть будь-якою мовою; торкніться лівої кнопки на HUD, щоб перемкнути A на літеру (E, S, R, F, C, G…) для примусового виводу. Додаткова мова з «Налаштування → Гаряча клавіша → Ваші мови» — це літера за замовчуванням.",
            .helpLangEnglishNote: "Примусова англійська + багатомовний Whisper: Raw використовує вбудований у Whisper переклад англійською, який працює на пристрої (швидко). Для якості обирайте Large v3 Full; Turbo легший, але менш надійний на довгому чи змішаному мовленні. Це стосується випадку, коли літера на HUD — E (ваша додаткова мова або обрана ціль).",
            .helpLangOtherNote: "Будь-який примусовий вивід не англійською (літера ≠ E) завжди потребує LLM після Whisper (хмарний або локальний MLX). Без активного рушія полірування примусовий вивід іспанською/російською/… не зможе змінити мову.",
            .helpLangWhere: "Літера на HUD (примусова ціль) за замовчуванням відповідає вашій додатковій мові з «Налаштування → Гаряча клавіша → Ваші мови». Якщо в «Гаряча клавіша» задано конкретну мову, то саме вона стає літерою. Якщо у «Гаряча клавіша» вибрано Auto, літера береться з «Глосарій → Мова автоперекладу», а потім — англійська. Змініть свою пару мов у «Налаштування → Гаряча клавіша → Ваші мови».",
            .helpModelsTitle: "Локальні моделі транскрипції",
            .helpModelsIntro: "Налаштування → Локальні моделі керує моделями WhisperKit Core ML, що перетворюють аудіо на текст на Apple Silicon. Це окремо від моделей доводки.",
            .helpModelsCatalog: "Лише англійська (Small/Medium .en): швидко, коли ви говорите лише англійською. Багатомовні Small/Medium: легші, кілька мов. Large v3 Turbo (~1,6 ГБ): швидка велика модель. Large v3 Full (~3 ГБ, найкраща якість): рекомендований стандартний варіант для точності й перекладу англійською.",
            .helpModelsRecommend: "Для змішаних мов і примусової англійської (літера HUD E) використовуйте багатомовну модель — в ідеалі Large v3 Full. Моделі лише для англійської не можуть нативно перекладати інші мови англійською.",
            .helpModelsUse: "Завантажити → Використати (активна лише одна). Видалити вилучає файли з цього Mac. Резервного варіанту Apple Speech немає — оберіть Локальний Whisper (із завантаженою моделлю) або Хмара · Google Gemini (потрібен ключ Google API).",
            .helpHotkeyTitle: "Налаштування гарячої клавіші",
            .helpHotkeyIntro: "Налаштування → Гаряча клавіша вмикає чотири незалежні глобальні сполучення. Увімкніть «Увімкнути гарячу клавішу», перш ніж будь-яке з них спрацює.",
            .helpHotkeyPrimary: "Основна (типово Option+S (⌥S)): почати/зупинити диктування в Оверлей HUD. Перше натискання записує (червоний), друге натискання обробляє (зелений) і доставляє Без обробки / Варіант 1 / Варіант 2.",
            .helpHotkeyPushToTalk: "Push-to-Talk (опціонально): увімкніть режим Push-to-Talk у Налаштування → Гарячі клавіші, щоб утримувати основну гарячу клавішу під час запису, а після відпускання автоматично виконати транскрипцію та доопрацювання — замість того щоб натискати один раз для старту й ще раз для зупинки.",
            .helpHotkeySecondary: "Вікно перекладу (типово Option+1): відкриває повну плаваючу панель перекладу. Це не гаряча клавіша запису — вона захоплює виділене/буфер обміну та перекладає. Стрілка скидання відновлює Option+1.",
            .helpHotkeyTertiary: "Швидкий переклад (типово Option+2): відкриває мінімальне вікно лише для читання з самим результатом перекладу. Натисніть гарячу клавішу ще раз або Escape, щоб закрити його.",
            .helpHotkeySettings: "Відкрити Налаштування (типово Option+~): відкриває вікно налаштувань Bolabol звідки завгодно, щоб ви могли перемикати моделі або мови, не виходячи із застосунку.",
            .helpModeQuickTitle: "Вікно швидкого перекладу",
            .helpModeQuickBody: "Третинна гаряча клавіша (типово Option+2) відкриває мінімальне вікно, що завжди зверху й показує лише результат перекладу — без панелі джерела та кнопок. Прочитайте його, потім натисніть Escape, щоб закрити. Для редагування чи повторного перекладу використовуйте повне Плаваюче вікно перекладу.",
            .helpFloatQuick: "Два вікна перекладу: Плаваюче вікно перекладу (Option+1) — це повна панель із вихідним текстом, меню постачальника/моделі та елементами керування; Швидкий переклад (Option+2) — мінімальне вікно лише для читання, що показує тільки результат. Використовуйте Швидкий переклад, коли потрібно лише прочитати переклад.",
            .helpHotkeyTarget: "Ціль диктування: який текст доставляється після запису — Без обробки, Варіант 1 чи Варіант 2. Той самий вибір, що й права кнопка HUD (R / 1 / 2).",
            .helpHotkeyMode: "Режим диктування: Буфер обміну копіює результат, щоб ви вставили його; Введення в активний застосунок вставляє текст у поле, яке було сфокусоване на початку запису.",
            .helpHotkeyAccess: "Введення в активний застосунок потребує дозволу на доступність (та сама сторінка налаштувань). Режим буфера обміну та Плаваюче вікно перекладу не потребують доступності для вставлення в панель — але захоплення тексту з інших застосунків через Command-C працює найкраще, коли застосунок є довіреним.",
            .helpFloatTitle: "Плаваюче вікно перекладу",
            .helpFloatIntro: "Панель утиліти зі змінним розміром, що завжди зверху (Bolabol Translation), окрема від головного зошита. Ідеальна для швидкої зміни мови, поки ви залишаєтеся у браузері, пошті чи чаті.",
            .helpFloatHotkey: "Відкрийте її гарячою клавішею «Вікно перекладу» (Налаштування → Гаряча клавіша → Вікно перекладу, типово Option+1). Ви також можете відкрити «Переклад» з нижньої панелі головного вікна; плаваюча панель має той самий інтерфейс.",
            .helpFloatCapture: "Під час відкриття Bolabol коротко надсилає Command-C найпереднішому застосунку, щоб скопіювати виділене, потім надає перевагу виділеному в нотатці, якщо ви всередині Bolabol, інакше — тексту в буфері обміну. Якщо щось захоплено та постачальника перекладу налаштовано, переклад починається автоматично.",
            .helpFloatPanel: "Усередині панелі: виберіть Постачальника і Модель, встановіть Цільову мову, редагуйте Оригінал, виконайте Переклад / Перекласти ще раз або запишіть короткий кліп для перекладу. Панель залишається плаваючою над іншими застосунками, її розмір можна змінювати.",
            .helpFloatFavorites: "Список моделей в інтерфейсі перекладу надає перевагу моделям, які ви позначили як улюблені в Налаштування → Постачальники API (пошуковий селектор ★). Якщо для цього постачальника немає улюблених, показується поточна вибрана модель.",
            .helpFloatDoubleClick: "Двічі клацніть область тексту «Оригінал» (джерело), щоб вставити з буфера обміну та одразу перекласти — зручно після того, як ви самі скопіювали текст.",
            .helpFloatEscape: "Натисніть Escape або кнопку закриття, щоб прибрати плаваючу панель. Закриття не завершує Bolabol.",
            .helpCloudTitle: "Хмарні постачальники API",
            .helpCloudIntro: "Налаштування → Постачальники API налаштовує хмарні LLM для доводки та перекладу — не для розпізнавання мовлення Whisper. Компонування: розкривний список постачальника вгорі, картка деталей, потім статистика використання.",
            .helpCloudProviders: "Порядок у списку: Google Gemini → OpenAI → Qwen → OpenRouter → Власний. (Anthropic не показано в поточному інтерфейсі.) Значок «Активний» позначає рушій, що використовується для доводки.",
            .helpCloudConfigure: "Виберіть постачальника, введіть ключ(і), відкрийте «Перегляд моделей» (аркуш із пошуком), виберіть текстову модель, потім «Використати для доводки». «Отримати ключ API» відкриває консоль постачальника, якщо доступна. Чипи моделі показують довжину контексту та, де доступно, ціни входу/виходу.",
            .helpCloudKeys: "Кілька ключів API: кожен постачальник може зберігати до 10 ключів (Додати ключ). Значок ока показує/приховує ключ. Для запитів використовується перший непорожній ключ; додаткові допомагають ротувати або тримати окремо особисті й робочі ключі.",
            .helpCloudFavorites: "У селекторі моделей позначайте моделі як улюблені (★). Улюблені впорядковуються вгорі та мають перевагу в меню моделей Плаваючого вікна перекладу. Улюблені зберігаються на цьому Mac.",
            .helpCloudOpenRouter: "OpenRouter: баланс рахунку в реальному часі (залишок у USD із кольоровим індикатором), каталог із пошуком, контекстом і цінами $/М токенів, а також керування оновленням. Перевіряйте баланс перед довгими сеансами.",
            .helpCloudBudget: "Повзунок бюджету OpenRouter — це особистий помічник м'якого ліміту в Налаштуваннях (візуальна підказка щодо того, скільки ви плануєте витратити) — сам по собі він не відключає API. Стежте за реальним банером балансу, щоб бачити залишок коштів.",
            .helpCloudCustom: "Власний: будь-який сумісний з OpenAI базовий URL + ключ (проксі, власний хостинг або ендпоінти постачальників). Моделі завантажуються з цього ендпоінта після встановлення ключа й URL.",
            .helpCloudStats: "Статистика використання внизу розділу Постачальники API: токени останньої транзакції та підсумки для вибраної моделі. «Скинути статистику» обнуляє ці лічильники.",
            .helpPolishTitle: "Доводка, MLX і промпти",
            .helpPolishIntro: "Транскрипція перетворює мовлення на текст. Доводка переписує цей текст. Вони використовують різні моделі та налаштування.",
            .helpPolishEngines: "Рушії: Доводку вимкнено (лише Без обробки) · Швидке локальне очищення (правила, без LLM, повністю офлайн) · Локальна модель MLX · Хмарний постачальник із Постачальників API. Ви можете перемикати постачальника/модель з панелі інструментів головної нотатки, а також з Налаштувань.",
            .helpPolishMLX: "Налаштування → Доводка: завантажте моделі з каталогу або скористайтеся «Сканувати локальні моделі» на диску. Надавайте перевагу instruct-моделям без розмірковування; моделі з розмірковуванням/мисленням повільніші й можуть вставляти ланцюжок думок у нотатку.",
            .helpPolishPrompts: "Налаштування → Промпти: редагуйте Варіант 1, Варіант 2 і Markdown. Кожен промпт має зберігати заповнювач \(PromptTemplate.transcriptionPlaceholder). Скидання відновлює вбудований шаблон.",
            .helpMoreTitle: "Глосарій, імпорт і переклад",
            .helpMoreGlossary: "Глосарій — це локальний словник бажаних написань і термінів (джерело → переклад, варіанти, категорії). Він не перенавчає Whisper; він переписує текст після розпізнавання/перекладу. Увімкніть його, додайте записи або виділіть текст у нотатці → Додати до глосарія. Експортуйте JSON перед очищенням. Мова автоперекладу тут підтримує режим літери HUD, коли мова гарячої клавіші — Авто.",
            .helpMoreImport: "Імпортуйте аудіо або перетягніть файл у вікно, щоб створити транскрибовану нотатку з активною мовною моделлю.",
            .helpMoreTranslate: "Перекладайте з головного вікна або через плаваючу панель Option+1 (Option+2 показує лише результат): виділене / буфер обміну / живе диктування → постачальник + модель + цільова мова. Переклад навмисно змінює мову; Варіант 1/2 зберігають ту саму мову. Режим літери HUD використовує рушій перекладу, коли ціль не англійська.",
            .helpPrivacyTitle: "Приватність, зберігання та діагностика",
            .helpPrivacyLocal: "Транскрипція Whisper, Швидке локальне очищення та локальна доводка MLX залишаються на цьому Mac. Записи зберігаються в локальних папках даних застосунку.",
            .helpPrivacyCloud: "Хмарна доводка та хмарний переклад надсилають ваш текст (і промпти) вибраному постачальнику. Використовуйте локальні рушії, коли нотатки мають залишатися приватними.",
            .helpPrivacyClear: "«Очистити все» назавжди видаляє всі нотатки та спорожняє папку записів, включно з осиротілим аудіо, що залишилося після перерваних сеансів. Спочатку експортуйте, якщо вміст для вас важливий.",
            .helpPrivacyLogs: "Загальні → Експорт системних журналів для діагностичного файлу. Використовуйте рівень журналювання Налагодження лише під час усунення неполадок. Тема, масштаб інтерфейсу, розмір/звуки HUD та мова інтерфейсу також містяться в розділі Загальні.",
            .helpTipsTitle: "Загальні поради",
            .helpTipEnglish: "Потрібен вивід англійською з інших мов? Багатомовний Whisper + літера HUD E (або Мова транскрипції = English) + Large v3 Full.",
            .helpTipNonEnglish: "Потрібен вивід іспанською/російською/…? Встановіть цю мову в розділі Гаряча клавіша, перемкніть HUD на літеру та тримайте активним хмарний або MLX-рушій доводки.",
            .helpTipDisk: "Диск заповнений моделями чи записами? Видаліть невикористані моделі Whisper у Локальних моделях; використовуйте «Очистити все», лише коли маєте намір стерти нотатки та залишкові файли .caf.",
            .helpTipStuck: "Гаряча клавіша чи введення зависли? Переконайтеся, що гарячу клавішу ввімкнено, мікрофон працює в головному вікні, надано доступність для режиму введення, потім спробуйте «Оновити стан». Експортуйте журнали, якщо проблема залишається.",
            // —— Legacy keys (partial locales + older references) ——
            .helpWelcomeTitle: "Довідка Bolabol",
            .helpWelcomeBody: "Диктуйте будь-де на вашому Mac. Мовлення транскрибується на пристрої за допомогою Whisper; текст може лишатися без обробки, бути очищеним або переписаним — а потім скопійованим чи введеним у застосунок, яким ви користувалися.",
            .helpQuickStart: "Почніть звідси (перші 5 хвилин)",
            .helpRecordStep: "Клацніть в іншому застосунку → натисніть гарячу клавішу (типово Option+S) → говоріть → натисніть ще раз, щоб зупинити. Червоний HUD = запис, зелений = обробка.",
            .helpVariantsStep: "Без обробки — це транскрипція. Варіант 1 — легке очищення. Варіант 2 — сильніше переписування. Markdown структурує доведений текст.",
            .helpCopyStep: "Скопіюйте поточну вкладку, «Копіювати всі» нотатки з бічної панелі або доставте через гарячу клавішу Буфер обміну / Введення в активний застосунок.",
            .helpRecordingTitle: "Оверлей HUD",
            .helpHUDStep: "HUD: [A|літера] хвиля [R|1|2]. Натисніть ліворуч A↔E, праворуч R→1→2. Перетягуйте будь-куди; розмір/звук у Загальні → Оверлей HUD.",
            .helpOfflineTranscription: "Локальні моделі транскрипції",
            .helpOfflineModelStep: "Налаштування → Локальні моделі: завантажте моделі WhisperKit. Обирайте Large v3 Full для якості й перекладу англійською.",
            .helpOfflineActivateStep: "Натисніть «Використати» на завантаженій моделі. «Видалити» звільняє місце на диску. Резервний варіант: Apple Speech.",
            .helpImportTitle: "Імпорт і переклад",
            .helpImportStep: "Імпортуйте аудіо або перетягніть файл у вікно, щоб транскрибувати як нову нотатку.",
            .helpTranslateStep: "Модальне вікно перекладу: виділене, буфер обміну або короткий запис → постачальник + цільова мова.",
            .helpPolishingProviders: "Рушії доводки",
            .helpPolishingProviderStep: "Вимкнено, Швидке локальне очищення, локальна MLX або хмарний постачальник API з Постачальників API.",
            .helpPromptsStep: "Налаштування → Промпти для Варіант 1, Варіант 2 і Markdown. Зберігайте заповнювач транскрипції.",
            .helpHotkeyStep: "Налаштування → Гаряча клавіша: увімкніть Option+S, виберіть Ціль і Режим, надайте доступність лише для введення в застосунки.",
            .helpPermissionsTitle: "Дозволи",
            .helpMicrophoneStep: "Мікрофон потрібен для запису у вікні та через HUD.",
            .helpAccessibilityStep: "Доступність потрібна лише для введення в активний застосунок.",
            .helpPermissionRefreshStep: "Якщо введення не працює, оновіть доступність у налаштуваннях гарячої клавіші або відкрийте Системні параметри.",
