            .accessibilityPermission: "Erişilebilirlik İzni",
            .accessibilityTrusted: "Verildi",
            .accessibilityNotTrusted: "Verilmedi",
            .accessibilityPermissionDescription: "Aktif Uygulamaya Yaz ve çevrilecek seçili metni yakalamak için gereklidir. Önceden kopyalanmış metni çevirmek Erişilebilirlik izni gerektirmez.",
            .requestAccessibilityPermission: "İzin İste",
            .openAccessibilitySettings: "Erişilebilirlik Ayarlarını Aç",
            .refreshPermissionStatus: "Durumu Yenile",
            // —— Help guide (primary) ——
            .helpHeroTitle: "Bolabol Yardım",
            .helpHeroSubtitle: "Mac'inizin her yerinde dikte edin. Konuşma, cihaz üzerinde Whisper ile metne çevrilir; metin ham kalabilir, temizlenebilir veya yeniden yazılabilir — ardından kopyalanır veya kullandığınız uygulamaya yazılır.",
            .helpStartTitle: "Buradan başlayın (ilk 5 dakika)",
            .helpStart1: "macOS istediğinde mikrofona izin verin. Onsuz kayıt başlatılamaz.",
            .helpStart2: "Ayarlar → Yerel Modeller'i açın, bir Whisper modeli indirin (Large v3 Full en iyi genel seçimdir), ardından Kullan'a basın.",
            .helpStart3: "Ayarlar → Kısayol Tuşu'nu açın, kısayol tuşlarını açın. Birincil (varsayılan Option+S) dikte eder. Çeviri Penceresi kısayol tuşu (varsayılan Option+1) tam yüzen çeviri panelini açar; Hızlı Çeviri (varsayılan Option+2) yalnızca sonucu gösterir; Ayarları Aç (varsayılan Option+~) tercihleri açar. Dikte için Hedef (Ham / Varyant 1 / Varyant 2) ve Mod (Pano veya Aktif Uygulamaya Yaz) seçin.",
            .helpStart4: "İsteğe bağlı: API Sağlayıcıları'nda bir bulut anahtarı ekleyin (sağlayıcı başına birkaç tane saklayabilirsiniz), bir model seçin, favorileri yıldızlayın, ardından İyileştirme için Kullan'a basın — ya da yerel bir MLX modeli kurun. Bir iyileştirme/çeviri motoru olmadan, Varyant 1/2 ve İngilizce olmayan zorunlu dil metni iyileştirmez.",
            .helpStart5: "Dikte: herhangi bir uygulamaya odaklanın → Option+S → konuşun → tekrar Option+S (kırmızı HUD = kayıt, yeşil = işleniyor). Anında çeviri: başka bir yerde metin seçin → Option+1 → yüzen panel seçimi/panoyu yakalar ve çevirir (Option+2 yalnızca sonucu gösterir).",
            .helpModesTitle: "Dört çalışma yolu",
            .helpModeWindowTitle: "Ana pencere",
            .helpModeWindowBody: "Notlar için bir not defteri: ses kaydedin veya içe aktarın, Ham / Varyant 1 / Varyant 2'yi inceleyin, iyileştirin, çevirin ve kopyalayın. Düzenlemek ve geçmişi saklamak istediğinizde en iyisidir.",
            .helpModeHotkeyTitle: "Kısayol Tuşu + Kaplama HUD",
            .helpModeHotkeyBody: "Başka bir uygulamanın içinde kalın. Birincil kısayol tuşu (Option+S) yüzen HUD ile kaydeder: dil modu (A / harf) ve çıktı hedefi (R / 1 / 2). HUD görünürken, iyileştirme sağlayıcısını değiştirmek için kaydırın ve belirli bir model seçmek için bir sağlayıcıya sağ tıklayın. Siz dikte ederken klavye odağını çalmaz.",
            .helpModeFloatTitle: "Yüzen Çeviri Penceresi",
            .helpModeFloatBody: "Çeviri Penceresi kısayol tuşu (varsayılan Option+1) her zaman üstte duran bir çeviri paneli açar. Aktif uygulamadan seçili metni (hızlı bir Command-C ile) alır, Orijinal'i doldurur ve anında çevirebilir. Tam dikte olmadan dil değişikliği gerektiğinde kullanın.",
            .helpWindowTitle: "Ana pencere",
            .helpWindowBody: "Sol: not listesi. Sağ: seçili not — ses bilgisi, iyileştirme sağlayıcı/model menüleri, metin sekmeleri ve eylem çubuğu.",
            .helpWindowNotes: "Kenar çubuğu: bir not seçin, Tümünü Kopyala veya Tümünü Temizle (kalıcı: diskteki her notu ve kalan kayıt dosyalarını siler).",
            .helpWindowTabs: "Sekmeler: Ham = saf transkripsiyon. Varyant 1 = hafif temizlik (dolgu sözcükleri, tekrarlar). Varyant 2 = netlik için daha güçlü yeniden yazım. Metni yapılandırmak için iyileştirilmiş bir sekmede Markdown eylemini kullanın. İstem yuvaları D/1/2/3/4, o varyant için hangi özel istemin etkin olduğunu değiştirir.",
            .helpWindowActions: "Alt çubuk: Kaydet / Durdur, Boş not, Ses İçe Aktar (veya bir dosyayı pencereye sürükleyin), Çevir, İyileştir, Kopyala. Ayarlar, Tercihler'i açar.",
            .helpWindowPolishingMenus: "Düzenleyicinin üzerinde İyileştirme Sağlayıcısı (Devre Dışı / Hızlı Temizlik / yerel MLX / bulut) ve İyileştirme Modeli (seçili bulut sağlayıcısı için modeller veya yerel MLX kartları) arasında geçiş yapabilirsiniz. Bu, nottan ayrılmadan Ayarlar → API Sağlayıcıları / İyileştirme ile eşleşir.",
            .helpHUDTitle: "Kaplama HUD (yüzen kapsül)",
            .helpHUDIntro: "Genel kısayol tuşuna bastığınızda, her uygulamanın üzerinde küçük yüzen bir kapsül belirir. Bu normal bir pencere değildir: her zaman üstte kalır, klavye odağını çalmaz ve yalnızca durumu gösterir — tam transkripsiyonu değil.",
            .helpHUDAnatomy: "Düzen soldan → sağa: (1) dil düğmesi  ·  (2) ortada canlı dalga biçimi  ·  (3) çıktı hedefi düğmesi. Ekranınızda genellikle  [ A ]  ≈≈≈  [ R ]  gibi görünür.",
            .helpHUDColorRed: "Mikrofon kaydederken ortadaki dalga biçimi kırmızıya döner. Kırmızıyken konuşun.",
            .helpHUDColorGreen: "Durdurduktan sonra (tekrar kısayol tuşu), dalga biçimi yeşile döner: Bolabol metne çeviriyor, gerekirse iyileştiriyor ve metni iletiyor. HUD gizlenene kadar bekleyin.",
            .helpHUDLeftTitle: "Sol düğme — dil modu (A ↔ harf)",
            .helpHUDLeftA: "A = Auto. Bolabol konuştuğunuz dili otomatik algılar. Döküm o dilde kalır (varsayılan olarak birincil dilinizde). Zorlanmış çeviri yok — Raw çıktıyı konuştuğunuz dilde istediğinizde bunu kullanın.",
            .helpHUDLeftLetter: "A yerine bir harf, \"çıktı dilini zorla\" anlamına gelir. Harf, o dilin İngilizce adının ilk harfidir: E = İngilizce, S = İspanyolca, R = Rusça, F = Fransızca, C = Çince, G = Almanca vb. Varsayılan olarak harf, Ayarlar → Kısayol Tuşu → Dilleriniz bölümündeki ek dilinizdir. Kısayol Tuşu → Döküm Dili belirli bir dil olarak ayarlanmışsa harf bunun yerine o dil olur.",
            .helpHUDLeftTap: "Sol düğmeye bir kez dokunarak A → harfe geçin (çıktı ek dile zorlanır), tekrar dokunarak harf → A'ya dönün (otomatik algılama). Seçim bir sonraki oturum için hatırlanır.",
            .helpHUDRightTitle: "Sağ düğme — çıktı hedefi (R → 1 → 2)",
            .helpHUDRightR: "R = Ham. Varyant 1 / Varyant 2 iyileştirmesi olmadan sade transkripsiyonu iletir. En hızlı yol; sol düğme E iken yine de Whisper İngilizce çevirisi kullanılabilir.",
            .helpHUDRightCycle: "1 = Varyant 1 (hafif temizlik). 2 = Varyant 2 (daha güçlü yeniden yazım). Bunlar etkin bir iyileştirme motoru (bulut veya yerel MLX) gerektirir. 1 veya 2'yi seçmek, devre dışıysa iyileştirmeyi yeniden açar.",
            .helpHUDRightTap: "R → 1 → 2 → R döngüsü için sağ düğmeye dokunun. Seçim, gelecekteki dikte için Kısayol Tuşu ayarlarında yeni varsayılan Hedef olur.",
            .helpHUDControlLanguage: "Sol: A = otomatik algılama (döküm konuşulan dilde). Harf (E, S, R, …) = çıktıyı o dile zorlar (varsayılan = ek dil). A ↔ harf arasında geçiş yapmak için dokunun.",
            .helpHUDControlTarget: "Sağ: R = Ham transkripsiyon, 1 = Varyant 1, 2 = Varyant 2. R → 1 → 2 → R döngüsü için dokunun.",
            .helpHUDDrag: "Sürükleme: kapsülün herhangi bir yerine (yalnızca düğmelere değil) tıklayıp basılı tutun ve herhangi bir ekranda herhangi bir yere taşıyın. Köşeye yakın, dock'un üstüne veya yazdığınız uygulamanın yanına koyun — nereye isterseniz.",
            .helpHUDSize: "Boyut ve saydamlık: Ayarlar → Genel → Kaplama HUD. Boyut kaydırıcısı tüm kapsülü (ve kaç spektrum çubuğu gördüğünüzü) ölçeklendirir. Saydamlık, cam arka planı soldurarak masaüstü içeriğinin az ya da çok görünmesini sağlar.",
            .helpHUDSound: "Sesler: aynı Genel → Kaplama HUD bölümü. “Başlangıçta/bitişte ses çal” seçeneğini değiştirin, Ses Seviyesi'ni ayarlayın ve kayıt olmadan önizlemek için HUD Seslerini Test Et'i kullanın. İpuçları kayıt başladığında ve işleme bittiğinde çalar.",
            .helpHUDSettingsPath: "Tüm HUD görünümü Ayarlar → Genel → Kaplama HUD altında bulunur (boyut, saydamlık, ses, seviye). Konum, sürükledikten sonra otomatik kaydedilir.",
            .helpHUDPosition: "HUD'u sürükledikten sonra Bolabol o konumu hatırlar ve bir sonraki sefer orada açılır.",
            .helpHUDDuration: "Ne kadar konuşabileceğinize dair kısa yapay bir sınır yoktur. Dalga biçimi kırmızıyken konuşmaya devam edin; bitince kısayol tuşuna tekrar basın.",
            .helpLangTitle: "Dil modları: ayrıntılar",
            .helpLangIntro: "Dil kontrolü, HUD'un sol düğmesi (A ↔ harf) ile Ayarlar → Kısayol Tuşu → Dilleriniz (birincil + ek) üzerinden yapılır. HUD harfi varsayılan olarak ek dilinizi gösterir. İkisi birlikte çalışır.",
            .helpLangAuto: "A (Auto): döküm, konuştuğunuz dilde kalır (varsayılan olarak birincil dilinizde). Zorlanmış çıktı olmadan her zamanki dilinizde not almak için idealdir.",
            .helpLangForced: "Harf (hedef zorlama): konuşma tanımanın ardından Bolabol dökümü ek dilinizde (veya seçtiğiniz başka bir dilde) sunabilir. Herhangi bir dilde konuşun; HUD'un sol düğmesine dokunarak A'dan harfe (E, S, R, F, C, G…) geçin ve çıktıyı zorlayın. Ayarlar → Kısayol Tuşu → Dilleriniz bölümündeki ek dil, varsayılan harf seçimidir.",
            .helpLangEnglishNote: "Zorlanmış İngilizce + çok dilli Whisper: Raw, Whisper'ın cihaz üzerindeki yerleşik İngilizceye çevirme özelliğini kullanır (hızlı). Kalite için Large v3 Full'i tercih edin; Turbo daha hafiftir ancak uzun veya karışık konuşmada daha az güvenilirdir. Bu, HUD harfi E olduğunda geçerlidir (ek diliniz veya seçtiğiniz bir hedef).",
            .helpLangOtherNote: "İngilizce dışındaki herhangi bir zorlanmış çıktı (harf ≠ E), Whisper'dan sonra her zaman bir LLM gerektirir (bulut veya yerel MLX). Etkin bir parlatma motoru olmadan, zorlanmış İspanyolca/Rusça/… gibi diller dönüştürülemez.",
            .helpLangWhere: "HUD harfi (hedef zorlama), varsayılan olarak Ayarlar → Kısayol Tuşu → Dilleriniz bölümündeki ek dilinizdir. Kısayol Tuşu dili belirli bir dile ayarlanmışsa o dil harf olur. Kısayol Tuşu Auto ise harf, Sözlük → Auto Translation Language'e, ardından İngilizce'ye geri döner. Dil çiftinizi Ayarlar → Kısayol Tuşu → Dilleriniz bölümünden değiştirin.",
            .helpModelsTitle: "Yerel transkripsiyon modelleri",
            .helpModelsIntro: "Ayarlar → Yerel Modeller, Apple Silicon'da sesi metne dönüştüren WhisperKit Core ML modellerini yönetir. Bu, iyileştirme modellerinden ayrıdır.",
            .helpModelsCatalog: "Yalnızca İngilizce (Small/Medium .en): yalnızca İngilizce konuştuğunuzda hızlı. Çok dilli Small/Medium: daha hafif çok dilli. Large v3 Turbo (~1,6 GB): hızlı büyük model. Large v3 Full (~3 GB, En iyi kalite): doğruluk ve İngilizce çeviri için önerilen varsayılan.",
            .helpModelsRecommend: "Karışık diller ve zorunlu İngilizce (HUD harfi E) için çok dilli bir model kullanın — ideal olarak Large v3 Full. Yalnızca İngilizce modeller diğer dilleri yerel olarak İngilizceye çeviremez.",
            .helpModelsUse: "İndir → Kullan (yalnızca biri etkin). Sil, dosyaları bu Mac'ten kaldırır. Apple Speech yedeği yoktur — Yerel Whisper (indirilmiş bir modelle) veya Bulut · Google Gemini (Google API anahtarı gerekir) seçin.",
            .helpHotkeyTitle: "Kısayol tuşu ayarları",
            .helpHotkeyIntro: "Ayarlar → Kısayol Tuşu dört bağımsız genel kısayolu etkinleştirir. Herhangi birinin çalışması için önce Kısayol tuşunu etkinleştir'i açın.",
            .helpHotkeyPrimary: "Birincil (varsayılan Option+S (⌥S)): Kaplama HUD'a dikteyi başlat/durdur. İlk basış kaydeder (kırmızı), ikinci basış işler (yeşil) ve Ham / Varyant 1 / Varyant 2'yi iletir.",
            .helpHotkeyPushToTalk: "Push-to-Talk (isteğe bağlı): Ayarlar → Kısayol Tuşu bölümünde Push-to-Talk Modunu açın; böylece kayıt sırasında birincil kısayol tuşunu basılı tutup bıraktığınızda otomatik olarak metne çevrilir ve iyileştirilir — başlatmak için bir kez, durdurmak için yeniden dokunmak yerine.",
            .helpHotkeySecondary: "Çeviri Penceresi (varsayılan Option+1): tam yüzen çeviri panelini açar. Bir kayıt kısayol tuşu değildir — seçimi/panoyu yakalar ve çevirir. Sıfırla oku Option+1'i geri yükler.",
            .helpHotkeyTertiary: "Hızlı Çeviri (varsayılan Option+2): yalnızca çevrilmiş sonucu gösteren minimal, salt okunur bir pencere açar. Kapatmak için kısayol tuşuna tekrar basın veya Escape'e basın.",
            .helpHotkeySettings: "Ayarları Aç (varsayılan Option+~): Bolabol ayarlar penceresini her yerden açar, böylece uygulamanızdan ayrılmadan model veya dil değiştirebilirsiniz.",
            .helpModeQuickTitle: "Hızlı Çeviri Penceresi",
            .helpModeQuickBody: "Üçüncül kısayol tuşu (varsayılan Option+2) yalnızca çevrilmiş sonucu gösteren minimal, her zaman üstte bir pencere açar — kaynak bölmesi yok, düğme yok. Okuyun, ardından kapatmak için Escape'e basın. Düzenleme veya yeniden çeviri için bunun yerine tam Yüzen Çeviri Penceresi'ni kullanın.",
            .helpFloatQuick: "İki çeviri penceresi: Yüzen Çeviri Penceresi (Option+1) kaynak metin, sağlayıcı/model menüleri ve denetimlerle tam paneldir; Hızlı Çeviri (Option+2) yalnızca sonucu gösteren minimal, salt okunur bir penceredir. Yalnızca bir çeviriyi okumanız gerektiğinde Hızlı Çeviri'yi kullanın.",
            .helpHotkeyTarget: "Dikte Hedefi: kayıttan sonra hangi metnin iletileceği — Ham, Varyant 1 veya Varyant 2. Sağ HUD düğmesiyle aynı seçim (R / 1 / 2).",
            .helpHotkeyMode: "Dikte Modu: Pano, yapıştırmanız için sonucu kopyalar; Aktif Uygulamaya Yaz, kayıt başladığında odaklanmış olan alana ekler.",
            .helpHotkeyAccess: "Aktif Uygulamaya Yaz, Erişilebilirlik izni gerektirir (aynı ayarlar sayfası). Pano modu ve Yüzen Çeviri Penceresi, panele yapıştırmak için Erişilebilirlik gerektirmez — ancak Command-C ile diğer uygulamalardan metin yakalama, uygulama güvenildiğinde en iyi çalışır.",
            .helpFloatTitle: "Yüzen Çeviri Penceresi",
            .helpFloatIntro: "Ana not defterinden ayrı, yeniden boyutlandırılabilir, her zaman üstte bir yardımcı program paneli (Bolabol Çeviri). Tarayıcıda, postada veya sohbette kalırken hızlı dil değişikliği için idealdir.",
            .helpFloatHotkey: "Çeviri Penceresi kısayol tuşuyla açın (Ayarlar → Kısayol Tuşu → Çeviri Penceresi, varsayılan Option+1). Ayrıca ana pencerenin alt çubuğundan Çevir'i açabilirsiniz; yüzen panel aynı arayüzü paylaşır.",
            .helpFloatCapture: "Açılışta Bolabol, herhangi bir seçimi kopyalamak için en öndeki uygulamaya kısaca Command-C gönderir, ardından Bolabol içindeyseniz not seçimini, aksi halde pano metnini tercih eder. Bir şey yakalandıysa ve bir çeviri sağlayıcısı ayarlandıysa, çeviri otomatik başlar.",
            .helpFloatPanel: "Panel içinde: Sağlayıcı ve Model seçin, Hedef Dil ayarlayın, Orijinal'i düzenleyin, Çevir / Tekrar Çevir çalıştırın veya çeviri için kısa bir klip kaydedin. Panel diğer uygulamaların üzerinde yüzen kalır ve yeniden boyutlandırılabilir.",
            .helpFloatFavorites: "Çeviri arayüzündeki model listesi, Ayarlar → API Sağlayıcıları'nda favori olarak yıldızladığınız modelleri tercih eder (aranabilir seçici ★). O sağlayıcı için favoriniz yoksa, şu anda seçili model gösterilir.",
            .helpFloatDoubleClick: "Panodan yapıştırmak ve anında çevirmek için Orijinal (kaynak) metin alanına çift tıklayın — metni kendiniz kopyaladıktan sonra kullanışlıdır.",
            .helpFloatEscape: "Yüzen paneli kapatmak için Escape'e veya kapat düğmesine basın. Kapatmak Bolabol'dan çıkmaz.",
            .helpCloudTitle: "Bulut API sağlayıcıları",
            .helpCloudIntro: "Ayarlar → API Sağlayıcıları, iyileştirme ve çeviri için bulut LLM'lerini yapılandırır — Whisper konuşma tanıma için değil. Düzen: üstte sağlayıcı açılır menüsü, ayrıntı kartı, ardından kullanım istatistikleri.",
            .helpCloudProviders: "Açılır menü sırası: Google Gemini → OpenAI → Qwen → OpenRouter → Özel. (Anthropic mevcut arayüzde gösterilmez.) Etkin rozeti, iyileştirme için kullanılan motoru işaretler.",
            .helpCloudConfigure: "Bir sağlayıcı seçin, anahtarları girin, Modelleri Gözat’ı (aranabilir sayfa) açın, bir metin modeli seçin, ardından İyileştirme için Kullan'a basın. API Anahtarı Al, kullanılabilir olduğunda sağlayıcının konsolunu açar. Model çipleri bağlam uzunluğunu ve kullanılabilir olduğunda giriş/çıkış fiyatlarını gösterir.",
            .helpCloudKeys: "Birden çok API anahtarı: her sağlayıcı en fazla 10 anahtar saklayabilir (Anahtar Ekle). Göz simgesi bir anahtarı gösterir/gizler. İlk boş olmayan anahtar istekler için kullanılır; fazladan anahtarlar döndürmenize veya kişisel ile iş anahtarlarını ayrı tutmanıza yardımcı olur.",
            .helpCloudFavorites: "Model seçicide modelleri favori olarak yıldızlayın (★). Favoriler en üste sıralanır ve Yüzen Çeviri Penceresi model menüsünde tercih edilir. Favoriler bu Mac'te saklanır.",
            .helpCloudOpenRouter: "OpenRouter: canlı hesap bakiyesi (renk kodlu kalan USD), bağlam ve $/M jeton fiyatlarıyla aranabilir katalog ve yenileme denetimi. Uzun oturumlardan önce bakiyeyi kontrol edin.",
            .helpCloudBudget: "OpenRouter bütçe kaydırıcısı, Ayarlar'da kişisel bir yumuşak sınır yardımcısıdır (ne kadar harcamayı planladığınıza dair görsel bir kılavuz) — API'yi tek başına kesmez. Kalan kredi için gerçek bakiye banner'ını izleyin.",
            .helpCloudCustom: "Özel: herhangi bir OpenAI uyumlu Temel URL + anahtar (proxy'ler, kendi kendine barındırılan veya satıcı uç noktaları). Anahtar ve URL ayarlandıktan sonra modeller o uç noktadan yüklenir.",
            .helpCloudStats: "API Sağlayıcıları'nın altındaki kullanım istatistikleri: son işlem jetonları ve seçili model için toplamlar. İstatistikleri Sıfırla bu sayaçları temizler.",
            .helpPolishTitle: "İyileştirme, MLX ve istemler",
            .helpPolishIntro: "Transkripsiyon konuşmayı metne dönüştürür. İyileştirme o metni yeniden yazar. Farklı modeller ve ayarlar kullanırlar.",
            .helpPolishEngines: "Motorlar: İyileştirme Devre Dışı (yalnızca Ham) · Hızlı Yerel Temizlik (kurallar, LLM yok, tamamen çevrimdışı) · Yerel MLX modeli · API Sağlayıcıları'ndan bulut sağlayıcı. Sağlayıcı/modeli ana not araç çubuğundan ve Ayarlar'dan değiştirebilirsiniz.",
            .helpPolishMLX: "Ayarlar → İyileştirme: katalog modellerini indirin veya diskte Yerel Modelleri Tara. Akıl yürütmeyen instruct modelleri tercih edin; akıl yürütme/düşünme modelleri daha yavaştır ve düşünce zincirini nota sızdırabilir.",
            .helpPolishPrompts: "Ayarlar → İstemler: Varyant 1, Varyant 2 ve Markdown'ı düzenleyin. Her istem \(PromptTemplate.transcriptionPlaceholder) yer tutucusunu korumalıdır. Sıfırla, yerleşik şablonu geri yükler.",
            .helpMoreTitle: "Sözlük, içe aktarma ve çeviri",
            .helpMoreGlossary: "Sözlük, tercih edilen yazımların ve terimlerin yerel bir sözlüğüdür (kaynak → çeviri, varyantlar, kategoriler). Whisper'ı yeniden eğitmez; tanıma/çeviri sonrasında metni yeniden yazar. Etkinleştirin, girdi ekleyin veya bir notta metin seçin → Sözlüğe Ekle. Temizlemeden önce JSON dışa aktarın. Buradaki Otomatik Çeviri Dili, Kısayol Tuşu dili Otomatik olduğunda HUD harf modunu destekler.",
            .helpMoreImport: "Etkin konuşma modeliyle transkripsiyonu yapılmış bir not oluşturmak için Ses İçe Aktar veya bir dosyayı pencereye bırakın.",
            .helpMoreTranslate: "Ana pencereden veya Option+1 yüzen paneliyle çevirin (Option+2 yalnızca sonucu gösterir): seçim / pano / canlı dikte → sağlayıcı + model + hedef dil. Çeviri dili bilerek değiştirir; Varyant 1/2 aynı dili korur. HUD harf modu, hedef İngilizce olmadığında çeviri motorunu kullanır.",
            .helpPrivacyTitle: "Gizlilik, depolama ve tanılama",
            .helpPrivacyLocal: "Whisper transkripsiyonu, Hızlı Yerel Temizlik ve yerel MLX iyileştirmesi bu Mac’te kalır. Kayıtlar uygulamanın yerel veri klasörlerinde saklanır.",
            .helpPrivacyCloud: "Bulut iyileştirmesi ve bulut çevirisi metninizi (ve istemleri) seçili sağlayıcıya gönderir. Notların gizli kalması gerektiğinde yerel motorları kullanın.",
            .helpPrivacyClear: "Tümünü Temizle, kesintiye uğrayan oturumların bıraktığı sahipsiz sesler dahil tüm notları kalıcı olarak siler ve kayıtlar klasörünü boşaltır. İçeriği önemsiyorsanız önce dışa aktarın.",
            .helpPrivacyLogs: "Tanılama dosyası için Genel → Sistem Günlüklerini Dışa Aktar. Hata Ayıklama günlük seviyesini yalnızca sorun giderirken kullanın. Tema, arayüz ölçeği, HUD boyutu/sesleri ve arayüz dili de Genel altındadır.",
            .helpTipsTitle: "Yaygın ipuçları",
            .helpTipEnglish: "Diğer dillerden İngilizce çıktı mı gerekiyor? Çok dilli Whisper + HUD harfi E (veya Transkripsiyon Dili = İngilizce) + Large v3 Full.",
            .helpTipNonEnglish: "İspanyolca/Rusça/… çıktısı mı gerekiyor? O dili Kısayol Tuşu altında ayarlayın, HUD'u harfe geçirin ve bir bulut veya MLX iyileştirme motorunu etkin tutun.",
            .helpTipDisk: "Disk model veya kayıtla mı dolu? Yerel Modeller'de kullanılmayan Whisper modellerini silin; Tümünü Temizle'i yalnızca notları ve kalan .caf dosyalarını silmek istediğinizde kullanın.",
            .helpTipStuck: "Kısayol tuşu veya yazma takıldı mı? Kısayol Tuşu'nun etkin olduğunu, mikrofonun ana pencerede çalıştığını, Yaz modu için Erişilebilirlik'in verildiğini doğrulayın, ardından Durumu yenile'yi deneyin. Hâlâ başarısız olursa günlükleri dışa aktarın.",
            // —— Legacy keys (partial locales + older references) ——
            .helpWelcomeTitle: "Bolabol Yardım",
            .helpWelcomeBody: "Mac'inizin her yerinde dikte edin. Konuşma, cihaz üzerinde Whisper ile metne çevrilir; metin ham kalabilir, temizlenebilir veya yeniden yazılabilir — ardından kopyalanır veya kullandığınız uygulamaya yazılır.",
            .helpQuickStart: "Buradan başlayın (ilk 5 dakika)",
            .helpRecordStep: "Başka bir uygulamaya tıklayın → kısayol tuşuna basın (varsayılan Option+S) → konuşun → durdurmak için tekrar basın. Kırmızı HUD = kayıt, yeşil = işleniyor.",
            .helpVariantsStep: "Ham, transkripsiyondur. Varyant 1 hafif temizliktir. Varyant 2 daha güçlü bir yeniden yazımdır. Markdown iyileştirilmiş metni yapılandırır.",
            .helpCopyStep: "Geçerli sekmeyi kopyalayın, kenar çubuğundan Tümünü Kopyala veya kısayol tuşuyla Pano / Aktif Uygulamaya Yaz ile iletin.",
            .helpRecordingTitle: "Kaplama HUD",
            .helpHUDStep: "HUD: [A|harf] dalga biçimi [R|1|2]. Sol A↔E, sağ R→1→2 dokunun. Her yere sürükleyin; boyut/ses Genel → Kaplama HUD'da.",
            .helpOfflineTranscription: "Yerel transkripsiyon modelleri",
            .helpOfflineModelStep: "Ayarlar → Yerel Modeller: WhisperKit modellerini indirin. Kalite ve İngilizce çeviri için Large v3 Full'ü tercih edin.",
            .helpOfflineActivateStep: "İndirilmiş bir modelde Kullan'a basın. Sil disk alanı boşaltır. Yedek: Apple Speech.",
            .helpImportTitle: "İçe aktarma ve çeviri",
            .helpImportStep: "Yeni bir not olarak metne çevirmek için Ses İçe Aktar veya bir dosyayı pencereye sürükleyin.",
            .helpTranslateStep: "Çeviri penceresi: seçim, pano veya kısa kayıt → sağlayıcı + hedef dil.",
            .helpPolishingProviders: "İyileştirme motorları",
            .helpPolishingProviderStep: "Devre Dışı, Hızlı Yerel Temizlik, yerel MLX veya API Sağlayıcıları'ndan bir bulut API sağlayıcısı.",
            .helpPromptsStep: "Varyant 1, Varyant 2 ve Markdown için Ayarlar → İstemler. Transkripsiyon yer tutucusunu koruyun.",
            .helpHotkeyStep: "Ayarlar → Kısayol Tuşu: Option+S'yi etkinleştirin, Hedef ve Mod seçin, Erişilebilirlik'i yalnızca uygulamalara yazmak için verin.",
            .helpPermissionsTitle: "İzinler",
            .helpMicrophoneStep: "Pencerede ve HUD aracılığıyla kayıt için mikrofon gereklidir.",
            .helpAccessibilityStep: "Erişilebilirlik yalnızca Aktif Uygulamaya Yaz için gereklidir.",
            .helpPermissionRefreshStep: "Yazma başarısız olursa, Kısayol Tuşu ayarlarında Erişilebilirlik'i yenileyin veya Sistem Ayarları'nı açın.",
            .helpPrivacyLocalStep: "Yerel Whisper ve yerel iyileştirme cihazda kalır.",
            .helpLogsStep: "Tanılama dosyası gerektiğinde Genel → Sistem Günlüklerini Dışa Aktar.",
