            // —— Help guide (primary) ——
            .helpHeroTitle: "Pomoc Bolabol",
            .helpHeroSubtitle: "Dyktuj w dowolnym miejscu na Macu. Mowa jest transkrybowana na urządzeniu za pomocą Whisper; tekst może pozostać surowy, zostać oczyszczony lub przepisany — a następnie skopiowany lub wpisany do aplikacji, której używasz.",
            .helpStartTitle: "Zacznij tutaj (pierwsze 5 minut)",
            .helpStart1: "Zezwól na dostęp do mikrofonu, gdy macOS o to poprosi. Bez tego nagrywanie nie może się rozpocząć.",
            .helpStart2: "Otwórz Ustawienia → Modele lokalne, pobierz model Whisper (Large v3 Full to najlepszy uniwersalny wybór), a następnie naciśnij Użyj.",
            .helpStart3: "Otwórz Ustawienia → Skrót klawiszowy, włącz skróty. Główny (domyślnie Option+S) to dyktowanie. Skrót Okno tłumaczenia (domyślnie Option+1) otwiera pełny pływający panel tłumaczenia; Szybkie tłumaczenie (domyślnie Option+2) pokazuje tylko wynik; Otwórz Ustawienia (domyślnie Option+~) otwiera preferencje. Dla dyktowania wybierz Cel (Surowy / Wariant 1 / Wariant 2) i Tryb (Schowek lub Wpisuj do aktywnej aplikacji).",
            .helpStart4: "Opcjonalnie: w Dostawcy API dodaj klucz chmurowy (możesz przechowywać kilka na dostawcę), wybierz model, oznacz ulubione gwiazdką, a następnie Użyj do korekty — lub zainstaluj lokalny model MLX. Bez silnika korekty/tłumaczenia Wariant 1/2 i wymuszony język inny niż angielski nie ulepszą tekstu.",
            .helpStart5: "Dyktowanie: uaktywnij dowolną aplikację → Option+S → mów → Option+S ponownie (czerwony HUD = nagrywanie, zielony = przetwarzanie). Natychmiastowe tłumaczenie: zaznacz tekst gdzie indziej → Option+1 → pływający panel przechwytuje zaznaczenie/schowek i tłumaczy (Option+2 pokazuje tylko wynik).",
            .helpModesTitle: "Cztery sposoby pracy",
            .helpModeWindowTitle: "Okno główne",
            .helpModeWindowBody: "Notatnik na notatki: nagrywaj lub importuj dźwięk, przeglądaj Surowy / Wariant 1 / Wariant 2, koryguj, tłumacz i kopiuj. Najlepszy, gdy chcesz edytować i zachować historię.",
            .helpModeHotkeyTitle: "Skrót klawiszowy + Nakładka HUD",
            .helpModeHotkeyBody: "Pozostań w innej aplikacji. Główny skrót (Option+S) nagrywa z pływającym HUD: tryb języka (A / litera) i cel wyjściowy (R / 1 / 2). Gdy HUD jest widoczny, przewiń, aby przełączyć dostawcę korekty, a kliknięcie prawym przyciskiem na dostawcę pozwala wybrać konkretny model. Nie przechwytuje fokusa klawiatury podczas dyktowania.",
            .helpModeFloatTitle: "Pływające okno tłumaczenia",
            .helpModeFloatBody: "Skrót Okno tłumaczenia (domyślnie Option+1) otwiera zawsze widoczny panel tłumaczenia. Przechwytuje zaznaczony tekst z aktywnej aplikacji (poprzez szybkie Command-C), wypełnia pole Oryginał i może natychmiast tłumaczyć. Użyj, gdy potrzebujesz zmiany języka bez pełnego dyktowania.",
            .helpWindowTitle: "Okno główne",
            .helpWindowBody: "Lewa strona: lista notatek. Prawa strona: wybrana notatka — informacje o dźwięku, menu dostawcy/modelu korekty, karty tekstowe i pasek akcji.",
            .helpWindowNotes: "Pasek boczny: wybierz notatkę, Kopiuj wszystko lub Wyczyść wszystko (trwałe: usuwa każdą notatkę i pozostałe pliki nagrań na dysku).",
            .helpWindowTabs: "Karty: Surowy = czysta transkrypcja. Wariant 1 = lekkie oczyszczenie (wypełniacze, powtórzenia). Wariant 2 = mocniejsze przepisanie dla jasności. Użyj akcji Markdown na skorygowanej karcie, aby ustrukturyzować tekst. Sloty promptów D/1/2/3/4 przełączają, który niestandardowy prompt jest aktywny dla danego wariantu.",
            .helpWindowActions: "Dolny pasek: Nagrywaj / Stop, Pusta notatka, Importuj dźwięk (lub przeciągnij plik na okno), Tłumacz, Koryguj, Kopiuj. Ustawienia otwierają Preferencje.",
            .helpWindowPolishingMenus: "Nad edytorem możesz przełączyć Dostawcę korekty (Wyłączony / Szybkie oczyszczanie / lokalny MLX / chmura) i Model korekty (modele dla wybranego dostawcy chmurowego lub lokalne karty MLX). Odpowiada to Ustawienia → Dostawcy API / Korekta bez opuszczania notatki.",
            .helpHUDTitle: "Nakładka HUD (pływająca kapsuła)",
            .helpHUDIntro: "Po naciśnięciu globalnego skrótu klawiszowego nad każdą aplikacją pojawia się mała pływająca kapsuła. Nie jest to zwykłe okno: pozostaje na wierzchu, nie przechwytuje fokusa klawiatury i pokazuje tylko status — nie pełną transkrypcję.",
            .helpHUDAnatomy: "Układ od lewej → do prawej: (1) przycisk języka  ·  (2) fala dźwiękowa na środku  ·  (3) przycisk celu wyjściowego. Na ekranie często wygląda jak  [ A ]  ≈≈≈  [ R ].",
            .helpHUDColorRed: "Środkowa fala dźwiękowa staje się czerwona, gdy mikrofon nagrywa. Mów, gdy jest czerwona.",
            .helpHUDColorGreen: "Po zatrzymaniu (ponowne naciśnięcie skrótu) fala dźwiękowa staje się zielona: Bolabol transkrybuje, koryguje w razie potrzeby i dostarcza tekst. Poczekaj, aż HUD się ukryje.",
            .helpHUDLeftTitle: "Lewy przycisk — tryb języka (A ↔ litera)",
            .helpHUDLeftA: "A = Auto. Bolabol automatycznie wykrywa język, w którym mówiłeś. Transkrypcja pozostaje w tym języku (domyślnie twój język główny). Bez wymuszonego tłumaczenia — używaj tego, gdy chcesz otrzymać wynik Raw w języku, w którym mówiłeś.",
            .helpHUDLeftLetter: "Litera zamiast A oznacza „wymuszony język wypowiedzi”. Litera to pierwsza litera angielskiej nazwy danego języka: E = angielski, S = hiszpański, R = rosyjski, F = francuski, C = chiński, G = niemiecki i tak dalej. Domyślnie litera to twój język dodatkowy z Ustawienia → Skrót klawiszowy → Twoje języki. Jeśli Skrót klawiszowy → Język transkrypcji ma ustawiony konkretny język, to ten język staje się literą.",
            .helpHUDLeftTap: "Dotknij lewego przycisku raz, aby przełączyć A → litera (wymuszenie wypowiedzi w języku dodatkowym), dotknij ponownie, aby przełączyć litera → A (automatyczne wykrywanie). Wybór zostanie zapamiętany na następną sesję.",
            .helpHUDRightTitle: "Prawy przycisk — cel wyjściowy (R → 1 → 2)",
            .helpHUDRightR: "R = Surowy. Dostarcza czystą transkrypcję bez korekty Wariant 1 / Wariant 2. Najszybsza ścieżka; nadal może używać tłumaczenia Whisper na angielski, gdy lewy przycisk to E.",
            .helpHUDRightCycle: "1 = Wariant 1 (lekkie oczyszczenie). 2 = Wariant 2 (mocniejsze przepisanie). Wymagają aktywnego silnika korekty (chmura lub lokalny MLX). Wybranie 1 lub 2 włącza korektę z powrotem, jeśli była wyłączona.",
            .helpHUDRightTap: "Naciśnij prawy przycisk, aby przełączać R → 1 → 2 → R. Wybór staje się nowym domyślnym Celem w ustawieniach Skrótu klawiszowego dla przyszłych dyktowań.",
            .helpHUDControlLanguage: "Lewy: A = automatyczne wykrywanie (transkrypcja w języku mówionym). Litera (E, S, R, …) = wymusza wypowiedź w tym języku (domyślnie język dodatkowy). Dotknij, aby przełączać A ↔ litera.",
            .helpHUDControlTarget: "Prawy: R = Surowa transkrypcja, 1 = Wariant 1, 2 = Wariant 2. Naciśnij, aby przełączać R → 1 → 2 → R.",
            .helpHUDDrag: "Przeciąganie: kliknij i przytrzymaj w dowolnym miejscu kapsuły (nie tylko na przyciskach) i przenieś ją w dowolne miejsce na dowolnym wyświetlaczu. Umieść ją blisko rogu, nad dockiem lub obok aplikacji, w której piszesz — gdziekolwiek chcesz.",
            .helpHUDSize: "Rozmiar i przezroczystość: Ustawienia → Ogólne → Nakładka HUD. Suwak Rozmiar skaluje całą kapsułę (i liczbę widocznych pasków widma). Przezroczystość wygasza szklane tło, dzięki czemu zawartość pulpitu prześwituje mniej lub bardziej.",
            .helpHUDSound: "Dźwięki: ta sama sekcja Ogólne → Nakładka HUD. Przełącz “Odtwarzaj dźwięk przy rozpoczęciu/zakończeniu”, ustaw Głośność dźwięku i użyj Testuj dźwięki HUD, aby odsłuchać bez nagrywania. Sygnały odtwarzane są przy rozpoczęciu nagrywania i po zakończeniu przetwarzania.",
            .helpHUDSettingsPath: "Cały wygląd i zachowanie HUD znajduje się w Ustawienia → Ogólne → Nakładka HUD (rozmiar, przezroczystość, dźwięk, głośność). Pozycja jest zapisywana automatycznie po przeciągnięciu.",
            .helpHUDPosition: "Po przeciągnięciu HUD Bolabol zapamiętuje to miejsce i otwiera się tam następnym razem.",
            .helpHUDDuration: "Brak krótkiego sztucznego limitu czasu mówienia. Mów dalej, gdy fala dźwiękowa jest czerwona; naciśnij skrót klawiszowy ponownie po zakończeniu.",
            .helpLangTitle: "Tryby językowe w szczegółach",
            .helpLangIntro: "Sterowanie językiem to lewy przycisk HUD (A ↔ litera) plus Ustawienia → Skrót klawiszowy → Twoje języki (główny + dodatkowy). Litera na HUD domyślnie odpowiada językowi dodatkowemu. Działają ze sobą.",
            .helpLangAuto: "A (Auto): transkrypcja pozostaje w języku, w którym mówiłeś (domyślnie twój język główny). Najlepsze do notatek w twoim zwykłym języku, bez wymuszania wypowiedzi.",
            .helpLangForced: "Litera (wymuszony język docelowy): po rozpoznaniu mowy Bolabol może dostarczyć transkrypcję w twoim języku dodatkowym (lub innym wybranym języku). Mów w dowolnym języku; dotknij lewego przycisku HUD, aby przełączyć z A na literę (E, S, R, F, C, G…) i wymusić wypowiedź. Domyślnym wyborem litery jest język dodatkowy z Ustawienia → Skrót klawiszowy → Twoje języki.",
            .helpLangEnglishNote: "Wymuszony angielski + wielojęzyczny Whisper: Raw korzysta z wbudowanego w Whisper tłumaczenia na angielski na urządzeniu (szybko). Dla jakości wybierz Large v3 Full; Turbo jest lżejszy, ale mniej niezawodny przy długiej lub mieszanej mowie. Dotyczy to sytuacji, gdy litera na HUD to E (twój język dodatkowy lub wybrany język docelowy).",
            .helpLangOtherNote: "Każda wymuszona wypowiedź w innym języku niż angielski (litera ≠ E) wymaga LLM po Whisper (chmura lub lokalny MLX). Bez aktywnego silnika Polishing wymuszony hiszpański/rosyjski/… nie może zmienić języka.",
            .helpLangWhere: "Litera na HUD (wymuszony język docelowy) domyślnie odpowiada twojemu językowi dodatkowemu z Ustawienia → Skrót klawiszowy → Twoje języki. Jeśli język skrótu klawiszowego jest ustawiony na konkretny język, to ten język staje się literą. Jeśli Skrót klawiszowy jest ustawiony na Auto, litera przechodzi do Słownik → Auto Translation Language, a następnie do angielskiego. Zmień swoją parę języków w Ustawienia → Skrót klawiszowy → Twoje języki.",
            .helpModelsTitle: "Lokalne modele transkrypcji",
            .helpModelsIntro: "Ustawienia → Modele lokalne zarządza modelami WhisperKit Core ML, które zamieniają dźwięk na tekst na Apple Silicon. Jest to oddzielne od modeli korekty.",
            .helpModelsCatalog: "Tylko angielski (Small/Medium .en): szybki, gdy mówisz tylko po angielsku. Wielojęzyczny Small/Medium: lżejszy wielojęzyczny. Large v3 Turbo (~1,6 GB): szybki duży model. Large v3 Full (~3 GB, Najlepsza jakość): zalecany domyślny dla dokładności i tłumaczenia na angielski.",
            .helpModelsRecommend: "Dla mieszanych języków i wymuszonego angielskiego (litera HUD E) użyj modelu wielojęzycznego — najlepiej Large v3 Full. Modele tylko angielskie nie mogą natywnie tłumaczyć innych języków na angielski.",
            .helpModelsUse: "Pobierz → Użyj (tylko jeden aktywny). Usuń usuwa pliki z tego Maca. Nie ma rezerwowego Apple Speech — wybierz Lokalny Whisper (z pobranym modelem) lub Chmura · Google Gemini (wymagany klucz Google API).",
            .helpHotkeyTitle: "Ustawienia skrótu klawiszowego",
            .helpHotkeyIntro: "Ustawienia → Skrót klawiszowy włącza cztery niezależne globalne skróty. Włącz Włącz skrót klawiszowy, zanim którykolwiek z nich zadziała.",
            .helpHotkeyPrimary: "Główny (domyślnie Option+S (⌥S)): rozpocznij/zatrzymaj dyktowanie do Nakładki HUD. Pierwsze naciśnięcie nagrywa (czerwony), drugie naciśnięcie przetwarza (zielony) i dostarcza Surowy / Wariant 1 / Wariant 2.",
            .helpHotkeyPushToTalk: "Push-to-Talk (opcjonalnie): włącz tryb Push-to-Talk w Ustawienia → Klawisz skrótu, aby przytrzymywać główny klawisz skrótu podczas nagrywania, a po zwolnieniu automatycznie transkrybować i dopracować — zamiast naciskać raz, aby rozpocząć, i ponownie, aby zatrzymać.",
            .helpHotkeySecondary: "Okno tłumaczenia (domyślnie Option+1): otwiera pełny pływający panel tłumaczenia. Nie jest to skrót nagrywania — przechwytuje zaznaczenie/schowek i tłumaczy. Strzałka resetowania przywraca Option+1.",
            .helpHotkeyTertiary: "Szybkie tłumaczenie (domyślnie Option+2): otwiera minimalne okno tylko do odczytu z samym przetłumaczonym wynikiem. Naciśnij skrót ponownie lub Escape, aby je zamknąć.",
            .helpHotkeySettings: "Otwórz Ustawienia (domyślnie Option+~): otwiera okno ustawień Bolabol z dowolnego miejsca, dzięki czemu możesz przełączać modele lub języki bez opuszczania aplikacji.",
            .helpModeQuickTitle: "Okno szybkiego tłumaczenia",
            .helpModeQuickBody: "Trzeciorzędny skrót (domyślnie Option+2) otwiera minimalne zawsze widoczne okno, które pokazuje tylko przetłumaczony wynik — bez panelu źródłowego, bez przycisków. Przeczytaj go, a następnie naciśnij Escape, aby zamknąć. Do edycji lub ponownego tłumaczenia użyj pełnego Pływającego okna tłumaczenia.",
            .helpFloatQuick: "Dwa okna tłumaczenia: Pływające okno tłumaczenia (Option+1) to pełny panel z tekstem źródłowym, menu dostawcy/modelu i elementami sterującymi; Szybkie tłumaczenie (Option+2) to minimalne okno tylko do odczytu pokazujące tylko wynik. Użyj Szybkiego tłumaczenia, gdy potrzebujesz tylko przeczytać tłumaczenie.",
            .helpHotkeyTarget: "Cel dyktowania: który tekst jest dostarczany po nagraniu — Surowy, Wariant 1 czy Wariant 2. Ten sam wybór co prawy przycisk HUD (R / 1 / 2).",
            .helpHotkeyMode: "Tryb dyktowania: Schowek kopiuje wynik do wklejenia; Wpisuj do aktywnej aplikacji wstawia do pola, które było aktywne, gdy rozpoczęto nagrywanie.",
            .helpHotkeyAccess: "Wpisuj do aktywnej aplikacji wymaga uprawnienia Dostępność (ta sama strona ustawień). Tryb Schowek i Pływające okno tłumaczenia nie wymagają Dostępności do wklejania do panelu — ale przechwytywanie tekstu z innych aplikacji przez Command-C działa najlepiej, gdy aplikacja jest zaufana.",
            .helpFloatTitle: "Pływające okno tłumaczenia",
            .helpFloatIntro: "Panel narzędziowy o zmiennym rozmiarze, zawsze na wierzchu (Bolabol Translation), oddzielny od głównego notatnika. Idealny do szybkiej zmiany języka, gdy pozostajesz w przeglądarce, poczcie lub czacie.",
            .helpFloatHotkey: "Otwórz go skrótem Okno tłumaczenia (Ustawienia → Skrót klawiszowy → Okno tłumaczenia, domyślnie Option+1). Możesz też otworzyć Tłumacz z dolnego paska okna głównego; pływający panel ma ten sam interfejs.",
            .helpFloatCapture: "Po otwarciu Bolabol krótko wysyła Command-C do aplikacji na wierzchu, aby skopiować zaznaczenie, a następnie preferuje zaznaczenie notatki, jeśli jesteś w Bolabol, w przeciwnym razie tekst ze schowka. Jeśli coś zostało przechwycone i dostawca tłumaczenia jest ustawiony, tłumaczenie rozpoczyna się automatycznie.",
            .helpFloatPanel: "Wewnątrz panelu: wybierz Dostawcę i Model, ustaw Język docelowy, edytuj Oryginał, uruchom Tłumacz / Tłumacz ponownie lub nagraj krótki klip do tłumaczenia. Panel pozostaje pływający nad innymi aplikacjami i można zmienić jego rozmiar.",
            .helpFloatFavorites: "Lista modeli w interfejsie tłumaczenia preferuje modele oznaczone gwiazdką jako ulubione w Ustawienia → Dostawcy API (wyszukiwalny selektor ★). Jeśli nie masz ulubionych dla tego dostawcy, pokazywany jest aktualnie wybrany model.",
            .helpFloatDoubleClick: "Kliknij dwukrotnie obszar tekstowy Oryginał (źródło), aby wkleić ze schowka i natychmiast przetłumaczyć — przydatne po samodzielnym skopiowaniu tekstu.",
            .helpFloatEscape: "Naciśnij Escape lub przycisk zamknięcia, aby odrzucić pływający panel. Zamknięcie nie kończy działania Bolabol.",
            .helpCloudTitle: "Dostawcy API w chmurze",
            .helpCloudIntro: "Ustawienia → Dostawcy API konfiguruje chmurowe LLM do korekty i tłumaczenia — nie do rozpoznawania mowy Whisper. Układ: lista rozwijana dostawców na górze, karta szczegółów, a następnie statystyki użycia.",
            .helpCloudProviders: "Kolejność na liście: Google Gemini → OpenAI → Qwen → OpenRouter → Niestandardowy. (Anthropic nie jest wyświetlany w bieżącym interfejsie.) Znaczek Aktywny oznacza silnik używany do korekty.",
            .helpCloudConfigure: "Wybierz dostawcę, wprowadź klucz(e), otwórz Przeglądaj modele (wyszukiwalny arkusz), wybierz model tekstowy, a następnie Użyj do korekty. Pobierz klucz API otwiera konsolę dostawcy, gdy jest dostępna. Znaczniki modeli pokazują długość kontekstu oraz, jeśli dostępne, ceny wejścia/wyjścia.",
            .helpCloudKeys: "Wiele kluczy API: każdy dostawca może przechowywać do 10 kluczy (Dodaj klucz). Ikona oka pokazuje/ukrywa klucz. Pierwszy niepusty klucz jest używany do żądań; dodatkowe pomagają rotować lub oddzielać klucze osobiste od służbowych.",
            .helpCloudFavorites: "W selektorze modeli oznaczaj modele gwiazdką jako ulubione (★). Ulubione są sortowane na górę i preferowane w menu modeli Pływającego okna tłumaczenia. Ulubione są przechowywane na tym Macu.",
            .helpCloudOpenRouter: "OpenRouter: saldo konta na żywo (kolorowe pozostałe USD), wyszukiwalny katalog z kontekstem i cenami $/M tokenów oraz kontrola odświeżania. Sprawdź saldo przed długimi sesjami.",
            .helpCloudBudget: "Suwak budżetu OpenRouter to osobisty pomocnik miękkiego limitu w Ustawieniach (wizualna wskazówka, ile zamierzasz wydać) — sam nie odcina API. Obserwuj baner rzeczywistego salda, aby sprawdzić pozostały kredyt.",
            .helpCloudCustom: "Niestandardowy: dowolny kompatybilny z OpenAI Bazowy URL + klucz (proxy, samodzielnie hostowane lub punkty końcowe dostawców). Modele ładują się z tego punktu końcowego po ustawieniu klucza i URL.",
            .helpCloudStats: "Statystyki użycia na dole Dostawców API: tokeny ostatniej transakcji i sumy dla wybranego modelu. Resetuj statystyki czyści te liczniki.",
            .helpPolishTitle: "Korekta, MLX i prompty",
            .helpPolishIntro: "Transkrypcja zamienia mowę na tekst. Korekta przepisuje ten tekst. Używają różnych modeli i ustawień.",
            .helpPolishEngines: "Silniki: Korekta wyłączona (tylko Surowy) · Szybkie lokalne oczyszczanie (reguły, bez LLM, w pełni offline) · Lokalny model MLX · Dostawca chmurowy z Dostawców API. Możesz przełączać dostawcę/model z paska narzędzi głównej notatki, jak i z Ustawień.",
            .helpPolishMLX: "Ustawienia → Korekta: pobierz modele z katalogu lub Skanuj w poszukiwaniu modeli lokalnych na dysku. Preferuj modele instruct bez rozumowania; modele rozumujące/myślące są wolniejsze i mogą wyciekać łańcuchem myśli do notatki.",
            .helpPolishPrompts: "Ustawienia → Prompty: edytuj Wariant 1, Wariant 2 i Markdown. Każdy prompt musi zachować symbol zastępczy \(PromptTemplate.transcriptionPlaceholder). Resetowanie przywraca wbudowany szablon.",
            .helpMoreTitle: "Słownik, import i tłumaczenie",
            .helpMoreGlossary: "Słownik to lokalny słownik preferowanych pisowni i terminów (źródło → tłumaczenie, warianty, kategorie). Nie trenuje ponownie Whisper; przepisuje tekst po rozpoznaniu/tłumaczeniu. Włącz go, dodaj wpisy lub zaznacz tekst w notatce → Dodaj do słownika. Wyeksportuj JSON przed Wyczyść. Język automatycznego tłumaczenia tutaj wspiera tryb litery HUD, gdy język Skrótu klawiszowego jest Auto.",
            .helpMoreImport: "Importuj dźwięk lub upuść plik na okno, aby utworzyć transkrybowaną notatkę z aktywnym modelem mowy.",
            .helpMoreTranslate: "Tłumacz z okna głównego lub przez pływający panel Option+1 (Option+2 pokazuje tylko wynik): zaznaczenie / schowek / dyktowanie na żywo → dostawca + model + język docelowy. Tłumaczenie celowo zmienia język; Wariant 1/2 zachowują ten sam język. Tryb litery HUD używa silnika tłumaczenia, gdy cel nie jest angielski.",
            .helpPrivacyTitle: "Prywatność, przechowywanie i diagnostyka",
            .helpPrivacyLocal: "Transkrypcja Whisper, Szybkie lokalne oczyszczanie i lokalna korekta MLX pozostają na tym Macu. Nagrania są przechowywane w lokalnych folderach danych aplikacji.",
            .helpPrivacyCloud: "Korekta w chmurze i tłumaczenie w chmurze wysyłają Twój tekst (i prompty) do wybranego dostawcy. Używaj lokalnych silników, gdy notatki muszą pozostać prywatne.",
            .helpPrivacyClear: "Wyczyść wszystko trwale usuwa wszystkie notatki i opróżnia folder nagrań, w tym osierocone pliki audio pozostawione przez przerwane sesje. Najpierw wyeksportuj, jeśli zależy Ci na zawartości.",
            .helpPrivacyLogs: "Ogólne → Eksportuj logi systemowe, aby uzyskać plik diagnostyczny. Używaj poziomu logów Debug tylko podczas rozwiązywania problemów. Motyw, skala interfejsu, rozmiar/dźwięki HUD i język interfejsu również znajdują się w Ogólne.",
            .helpTipsTitle: "Wskazówki",
            .helpTipEnglish: "Potrzebujesz angielskiego wyniku z innych języków? Wielojęzyczny Whisper + litera HUD E (lub Język transkrypcji = angielski) + Large v3 Full.",
            .helpTipNonEnglish: "Potrzebujesz wyniku w hiszpańskim/rosyjskim/…? Ustaw ten język w Skrócie klawiszowym, przełącz HUD na literę i utrzymuj aktywny silnik korekty w chmurze lub MLX.",
            .helpTipDisk: "Dysk pełen modeli lub nagrań? Usuń nieużywane modele Whisper w Modelach lokalnych; użyj Wyczyść wszystko tylko, gdy zamierzasz wyczyścić notatki i pozostałe pliki .caf.",
            .helpTipStuck: "Skrót klawiszowy lub wpisywanie nie działa? Potwierdź, że Skrót klawiszowy jest włączony, mikrofon działa w oknie głównym, Dostępność jest przyznana dla trybu Wpisuj, a następnie spróbuj Odśwież status. Wyeksportuj logi, jeśli nadal nie działa.",
            // —— Legacy keys (partial locales + older references) ——
            .helpWelcomeTitle: "Pomoc Bolabol",
            .helpWelcomeBody: "Dyktuj w dowolnym miejscu na Macu. Mowa jest transkrybowana na urządzeniu za pomocą Whisper; tekst może pozostać surowy, zostać oczyszczony lub przepisany — a następnie skopiowany lub wpisany do aplikacji, której używasz.",
            .helpQuickStart: "Zacznij tutaj (pierwsze 5 minut)",
            .helpRecordStep: "Kliknij w inną aplikację → naciśnij skrót klawiszowy (domyślnie Option+S) → mów → naciśnij ponownie, aby zatrzymać. Czerwony HUD = nagrywanie, zielony = przetwarzanie.",
            .helpVariantsStep: "Surowy to transkrypcja. Wariant 1 to lekkie oczyszczenie. Wariant 2 to mocniejsze przepisanie. Markdown strukturyzuje skorygowany tekst.",
            .helpCopyStep: "Skopiuj bieżącą kartę, Kopiuj wszystkie notatki z paska bocznego lub dostarcz przez skrót klawiszowy Schowek / Wpisuj do aktywnej aplikacji.",
            .helpRecordingTitle: "Nakładka HUD",
            .helpHUDStep: "HUD: [A|litera] fala dźwiękowa [R|1|2]. Naciśnij lewy A↔E, prawy R→1→2. Przeciągnij w dowolne miejsce; rozmiar/dźwięk w Ogólne → Nakładka HUD.",
            .helpOfflineTranscription: "Lokalne modele transkrypcji",
            .helpOfflineModelStep: "Ustawienia → Modele lokalne: pobierz modele WhisperKit. Preferuj Large v3 Full dla jakości i tłumaczenia na angielski.",
            .helpOfflineActivateStep: "Naciśnij Użyj na pobranym modelu. Usuń zwalnia miejsce na dysku. Rezerwa: Apple Speech.",
            .helpImportTitle: "Import i tłumaczenie",
            .helpImportStep: "Importuj dźwięk lub przeciągnij plik na okno, aby transkrybować jako nową notatkę.",
            .helpTranslateStep: "Okno tłumaczenia: zaznaczenie, schowek lub krótkie nagranie → dostawca + język docelowy.",
            .helpPolishingProviders: "Silniki korekty",
            .helpPolishingProviderStep: "Wyłączony, Szybkie lokalne oczyszczanie, lokalny MLX lub dostawca API w chmurze z Dostawców API.",
            .helpPromptsStep: "Ustawienia → Prompty dla Wariant 1, Wariant 2 i Markdown. Zachowaj symbol zastępczy transkrypcji.",
            .helpHotkeyStep: "Ustawienia → Skrót klawiszowy: włącz Option+S, wybierz Cel i Tryb, przyznaj Dostępność tylko do wpisywania do aplikacji.",
            .helpPermissionsTitle: "Uprawnienia",
            .helpMicrophoneStep: "Mikrofon jest wymagany do nagrywania w oknie i przez HUD.",
            .helpAccessibilityStep: "Dostępność jest wymagana tylko dla Wpisuj do aktywnej aplikacji.",
            .helpPermissionRefreshStep: "Jeśli wpisywanie nie działa, odśwież Dostępność w ustawieniach Skrótu klawiszowego lub otwórz Ustawienia systemowe.",
